insert into _hedef (id, yerel, sutun, eski, yeni, kaynak) values
  ('8800d2fb-b58b-5a97-aeac-15270193a913','offline_6059','explanation_tr','"hewran": diğer giysilerin üstüne giyilen uzun üstlük (aba).','Hewran, öteki giysilerin üstüne giyilen uzun dış giysidir; günlük giysi katı değil, en üstteki örtü katıdır.','tr'),
  ('b0a0fca8-aa88-5f74-a85a-16119b8655eb','offline_6093','explanation_tr','"tûrik": yiyecek taşımak için dokunan torba.','Tûrik dokuma bir torbadır; yolda ya da tarlada ekmek ve azık taşımak için kullanılır.','tr'),
  ('a7f1b481-b1e1-5559-975e-c29ae42be8b1','offline_6117','explanation_tr','"nanê tenûrê": tandırda pişirilen geleneksel ekmek.','Nanê tenûrê, tandırın (tenûr) iç duvarına yapıştırılarak pişirilen ince ekmektir; adı da pişirildiği ocaktan gelir.','tr'),
  ('4e28dece-a151-5b47-8d78-2abe2bc43d93','offline_6136','explanation_tr','"koçerî": göçer yaşam tarzı ve dans ritmi.','Koçerî, yaz yaylası (zozan) ile kışlık (germiyan) arasında mevsimlik göçe dayanan yaşam biçimidir; aynı adla anılan bir govend ritmi de vardır.','tr'),
  ('992b5825-d7da-528f-84c0-11d4b53b4e4a','offline_6189','explanation_tr','"cîranî": komşuluk ve toplumsal yardımlaşma.','Cîranî, "cîran" (komşu) sözcüğünden gelir; komşuluk ilişkisini ve komşular arası yardımlaşmayı anlatır.','tr'),
  ('056a6a6f-6811-5da1-8660-f4e31476c213','offline_6457','explanation_tr','"şabaş": müzisyenlere bahşiş atma geleneği.','Şabaş, düğün ve şenliklerde para ya da armağan verme geleneğidir; birçok yörede çalgıcılara ve dengbêjlere verilen bahşişi anlatır.','tr'),
  ('d82f6053-3c83-5856-a18a-1fcae2184ee1','offline_6465','explanation_tr','"sersal": Kürt halk takviminde yılbaşı kutlaması.','Sersal, "ser" (baş) ve "sal" (yıl) sözcüklerinden oluşur; halk takviminde yeni yılın başlangıcını kutlamayı anlatır.','tr'),
  ('536d2683-b5d1-56db-9934-3c015ffb93d5','offline_6533','explanation_tr','"masal anlatımı": kuşaktan kuşağa aktarılan anlatı.','Masallar sözlü gelenekte kuşaktan kuşağa anlatılarak aktarılır; zamanla yazıya geçirilerek de korunur.','tr'),
  ('c1900627-a209-52f4-a198-d4b85eb58581','offline_6538','explanation_tr','"şevbêrk": kış gecelerinde yapılan sohbet toplantıları.','Şevbêrk, uzun kış gecelerinde komşuların bir evde toplanıp masal, kilam ve sohbetle vakit geçirdiği toplantıdır.','tr'),
  ('6e9f8007-63ad-5c56-b456-42cb3b7a3d93','offline_6730','explanation_tr','"serpêhatî": yaşanmış ilginç olayların anlatımı.','Serpêhatî, birinin başından geçmiş, yaşanmış olayları anlatan anlatıdır; hayal ürünü masaldan bu yönüyle ayrılır.','tr'),
  ('aaadbd89-176c-5541-aee0-4a3785b2729f','offline_6835','explanation_tr','"qutik": geleneksel Kürt yeleği veya giysisi.','Qutik, geleneksel giyimde yelek ya da üst giysi için kullanılan addır; öteki seçenekler giysi değil, başka kültür öğeleridir.','tr'),
  ('8ff79e66-cf2b-526a-b1ad-3c7413d73fc8','offline_6841','explanation_tr','"reşmal": siyah keçi kılından yapılan çadır.','Reşmal "kara ev" demektir: göçerlerin keçi kılından dokunan çadırıdır; kıl yağmurda şişerek su geçirmez.','tr'),
  ('b74aada5-767d-5b34-983c-c53c92f8b4e4','offline_7066','explanation_tr','"Dersim 1937": 1937-38 Dersim harekâtı, çatışmalar ve kitlesel öldürmeler.','Dersim 1937–38, devletin bölgede yürüttüğü askerî harekâtı ve bu sırada yaşanan toplu öldürme ve sürgünleri anlatır.','tr'),
  ('eecba717-363e-569d-9e6e-3a90d9bae4a2','offline_7145','explanation_tr','"Şeyh Said": 1925 Şeyh Said İsyanı''nın başlıca lideri.','Şeyh Said, 1925 ayaklanmasının lideriydi; ayaklanmanın dinî ve Kürt ulusal boyutları tarihçilerce farklı değerlendirilir. Ayaklanma bastırıldı ve Şeyh Said aynı yıl Diyarbakır''da idam edildi.','tr'),
  ('a1f9f20b-0554-5687-9664-e06b387ff657','offline_7151','explanation_tr','"Baban Emirliği": Süleymaniye merkezli güçlü Kürt prensliği.','Baban Beyliği, merkezi Silêmanî (Süleymaniye) olan güçlü bir Kürt beyliğiydi; kent 1784''te Babanlar tarafından kuruldu.','tr'),
  ('06d3f7a1-e623-5400-a584-b08308cb429d','offline_7223','explanation_tr','"Kasr-ı Şirin Antlaşması": Osmanlı ve Safevi sınırını belirleyen antlaşma.','Kasr-ı Şirin Antlaşması (1639) Osmanlı–Safevi sınırını düzenledi ve Kürtlerin yaşadığı bölgelerin iki devlet arasındaki paylaşımını büyük ölçüde pekiştirdi.','tr'),
  ('ae03650d-527b-5848-867f-cffc9187f457','offline_7249','explanation_tr','"Şeyh Mahmud Berzenci": Irak''ta kendini Kürdistan kralı ilan eden lider.','Şeyh Mahmud Berzenci, 1920''lerde Süleymaniye''de kendini Kürdistan kralı (hükümdarı) ilan etti ve İngiliz yönetimine karşı direndi.','tr'),
  ('51cf256f-3581-5fcb-9f08-0229341c4780','offline_7300','explanation_tr','"Mela Mahmude Bayazidi": Kürt örf adetlerini derleyen ilk araştırmacı.','Mela Mehmûdê Bazîdî, 19. yüzyılda Kürt örf ve âdetlerini Kürtçe olarak derleyen öncü eseri hazırladı; çalışma Rus diplomat Aleksandr Jaba''nın teşvikiyle yazıldı.','tr'),
  ('1a22fe3e-1366-5098-8d04-798bc1e8e936','offline_7417','explanation_tr','"şîroveya dîrokî": kanıtlardan anlam çıkarma.','Tarihî yorum, kaynaklardaki kanıtları karşılaştırıp onlardan anlam ve sonuç çıkarmaktır; yalnızca olayları sıralamak yorum değildir.','tr'),
  ('cc708a55-98ca-53f1-b6c8-208f802c7df6','offline_7474','explanation_tr','"sözlü tarih": tanıklık ve anlatılarla geçmişi anlama yöntemi.','Dîroka devkî (sözlü tarih), geçmişi olayları yaşamış ya da duymuş kişilerin sözlü tanıklıkları üzerinden araştırır; bu tanıklıklar yazılı belgeler ve öteki kaynaklarla birlikte değerlendirilir.','tr'),
  ('8614c98b-9514-5398-9501-ba79056f87e4','offline_7497','explanation_tr','"Mustafa Barzani": Kürt ulusal hareketinin askerî ve siyasî liderlerinden biri.','Mustafa Barzani (1903–1979), Güney Kürdistan''daki Kürt hareketinin uzun yıllar askerî ve siyasi önderliğini yaptı; Mahabad Cumhuriyeti''nin ordusunda da komutandı.','tr'),
  ('5c89b78c-9abb-51c9-b8f7-2d05f939e98b','offline_7507','explanation_tr','"göç": toplulukların yer değiştirmesi.','Göç, insan topluluklarının yaşadığı yeri savaş, geçim ya da baskı gibi nedenlerle değiştirmesidir; geçici ya da kalıcı olabilir.','tr'),
  ('43d87741-9576-5920-ad2e-10a58a68ce2d','offline_7605','explanation_tr','"birincil kaynak": Döneminden kalan belge veya nesne (birincil kaynak).','Birincil kaynak, araştırılan konuya doğrudan tanıklık eden ya da özgün veri sunan kaynaktır; dönemin belgeleri, nesneleri ve tanık anlatıları buna örnektir.','tr'),
  ('f580690b-21d1-5b8a-9f80-4e1778aeb76f','offline_7643','explanation_tr','"Mikdat Mithat Bedirxan": 1898''de ilk Kürtçe gazete Kurdistan''ı çıkaran kişi.','Mikdat Mithat Bedirxan, ilk Kürtçe gazete olan Kurdistan''ı 22 Nisan 1898''de Kahire''de yayımlamaya başladı; bu tarih Kürt basın günü olarak anılır.','tr'),
  ('c6a33f83-73cc-52e7-ab5f-a1440cc5d626','offline_7763','explanation_tr','"Bohtan Emirliği": Cizre merkezli önemli Kürt beyliği.','Botan Beyliği''nin merkezi Cizre''ydi (Cizîra Botan); son büyük beyi Bedirxan Bey 1847''de Osmanlı''ya yenildi.','tr'),
  ('4cbea941-2a07-5c24-8b0b-7576468bc76a','offline_7798','explanation_tr','"Îhsan Nûrî Paşa": Hoybun cemiyeti adına askeri liderlik yapan subay.','Îhsan Nûrî Paşa, Hoybûn cemiyetinin desteklediği Ağrı (Ararat) ayaklanmasının (1927–1930) askerî komutanıydı.','tr'),
  ('ba592679-02c6-5cc1-818b-22f10dcdca19','offline_7852','explanation_tr','"Kovara Hawar": Latin alfabesiyle basılan ilk Kürtçe dergi.','Hawar dergisi 1932''de Şam''da Celadet Alî Bedirxan tarafından çıkarıldı; Latin harfli Kurmancî alfabesini yaydı.','tr'),
  ('275b9299-3d48-591a-9ea6-492bc702f907','offline_7905','explanation_tr','"Kampanyaya Enfalê": Irak rejimi tarafından Kürtlere yönelik soykırım.','Enfal, Irak''taki Baas rejiminin 1988''de Kürtlere karşı yürüttüğü kampanyadır; köyler yıkıldı, on binlerce insan öldürüldü. Birçok ülke ve kurum bunu soykırım olarak tanır.','tr'),
  ('c362c08b-fe14-517f-8250-4cab07423e09','offline_8023','explanation_tr','"Heskîf": Dicle nehri üzerinde yer alan binlerce yıllık tarihi kent.','Heskîf (Hasankeyf), Dicle kıyısında kayalara oyulmuş mağara yerleşimleriyle bilinen çok eski bir kenttir; Ilısu Barajı''nın suları eski kentin büyük bölümünü 2020''de kapladı.','tr'),
  ('181dcca2-6fa9-5d45-8b2c-3c46c4cedb88','offline_8141','explanation_tr','"Derbendihan gölü": Diyala nehri üzerinde kurulmuş baraj gölü.','Derbendîxan Gölü, Diyala (Sîrwan) Nehri üzerine kurulan barajın oluşturduğu yapay göldür; doğal göl değildir.','tr'),
  ('3ac95f40-e4d2-509a-ac6b-2316aaafff60','offline_8200','explanation_tr','"Siverek ovası": Karacadağ lavlarının oluşturduğu taşlık plato.','Siverek Ovası (Deşta Sêwregê), Karacadağ''dan akan bazalt lavlarının örttüğü taşlık bir düzlüktür; bu yüzden toprağı taşlıdır.','tr'),
  ('d5fef95b-da03-593d-80fb-c7853af3eaa1','offline_8255','explanation_tr','"Zagros sıradağları": Kürdistan coğrafyasını baştan başa bölen dağlar.','Zagros sıradağları kuzeybatı–güneydoğu doğrultusunda uzanır ve Kürdistan coğrafyasının omurgasını oluşturur.','tr'),
  ('366222d8-55ed-53e3-ab3a-98012fece2e6','offline_8384','explanation_tr','"Hewlêr ovası": Güney Kürdistan''ın verimli tarım ovalarından biri.','Hewlêr (Erbil) Ovası, Büyük ve Küçük Zap arasında uzanan verimli bir düzlüktür; tahıl tarımıyla bilinir.','tr'),
  ('c33e360d-6b01-535b-9d45-cc6a5899f8f8','offline_8480','explanation_tr','"Karacadağ": Diyarbakır ovasında yer alan yayvan bazaltik volkan.','Karacadağ (Qerejdax), Diyarbakır ile Urfa arasında yayılan geniş ve alçak bir kalkan volkanıdır; çevresindeki bazalt taşlar Amed surlarında da kullanılmıştır.','tr'),
  ('bc8f62d2-023f-5ff9-9866-269807506092','offline_8523','explanation_tr','"Dicle nehri": Diyarbakır surlarının altından geçen nehir.','Dicle, Diyarbakır''ın tarihî surlarının aşağısındaki vadiden akar; Hevsel Bahçeleri surlarla nehir arasındaki alandadır.','tr'),
  ('cc221d3b-f542-54d4-9969-69e9d9df2f36','offline_8532','explanation_tr','"Dokan gölü": Süleymaniye yakınlarında yer alan yapay baraj gölü.','Dokan Gölü, Küçük Zap üzerine kurulan barajın oluşturduğu yapay göldür ve Süleymaniye iline bağlıdır.','tr'),
  ('85e345da-da12-5082-90cc-cced11451cb9','offline_8539','explanation_tr','"Kürdistan iklimi": karasal ve dağlık alanlarda soğuk kışlar.','Kürdistan''ın büyük bölümünde karasal iklim hâkimdir: yükseklik ve denizden uzaklık nedeniyle kışlar soğuk ve karlı, yazlar sıcak ve kurak geçer.','tr'),
  ('41665ecf-07e3-5ff9-8e6d-aa347103af83','offline_8603','explanation_tr','"Hazar gölü": Elazığ sınırlarında yer alan tektonik göl.','Hazar Gölü, Elazığ''da Doğu Anadolu Fay Hattı üzerinde oluşmuş tektonik bir göldür; Dicle bu göl yöresinden doğar.','tr'),
  ('eea6815d-efe3-564d-a823-173738e4f778','offline_8950','explanation_tr','"Dokan gölü": Süleymaniye yakınlarında yer alan yapay baraj gölü.','Dokan Gölü, Küçük Zap üzerindeki Dokan Barajı ile oluşmuş yapay göldür; Süleymaniye yakınındadır.','tr'),
  ('2fe04d59-bcbe-523a-bf78-61f211522280','offline_9132','explanation_tr','"Habur çayı": Türkiye ve Irak sınırını çizen Dicle kolu.','Habur Çayı, Zaho yakınından geçip Dicle''ye karışan bir koldur; bir kesiminde Türkiye–Irak sınırını oluşturur.','tr'),
  ('3778b742-5722-5f4b-b6fc-c60c0fa3f570','offline_9207','explanation_tr','"Ronahî dergisi": Şam''da Latin alfabesiyle çıkarılan edebi dergi.','Ronahî dergisi 1942–1945 arasında Şam''da Celadet Alî Bedirxan tarafından çıkarıldı; Hawar''ın kardeş yayınıydı ve resimliydi.','tr'),
  ('5f0a48c4-22df-58a6-985e-971081806482','offline_9227','explanation_tr','"Cegerxwîn": modern Kürt şiirinin öncü toplumcu şairi.','Cegerxwîn (1903–1984), klasik biçimlerden de yararlanarak şiirinde halkın yaşamını, toplumsal hakları ve özgürlüğü işledi; modern toplumcu Kürt şiirinin öncülerinden sayılır.','tr'),
  ('ff6ea5ed-7d02-518c-8737-82c3e09423ba','offline_9410','explanation_tr','"destana Memê Alan": Ehmedê Xanî''nin Mem û Zîn''e ilham aldığı halk destanı.','Memê Alan sözlü bir halk destanıdır; Ehmedê Xanî 1692''de yazdığı Mem û Zîn mesnevisinde bu anlatıdan yararlandı.','tr'),
  ('c2532d7c-87e6-56a9-899f-53defea20d83','offline_9434','explanation_tr','"Riya Taza gazetesi": Erivan''da uzun yıllar basılan Kürtçe gazete.','Riya Taza, 1930''da Erivan''da yayımlanmaya başlayan Kürtçe gazetedir; yayını bir süre kesildikten sonra 1955''te yeniden başladı.','tr'),
  ('4ddd8267-674e-562f-be9a-b11e699fb4de','offline_9456','explanation_tr','"Xanî Mektebi": Ehmedê Xanî''nin başlattığı edebi ve düşünsel ekol.','Xanî Mektebi, Ehmedê Xanî''nin Kürtçeyi bilim ve edebiyat dili yapma çabasından doğan ekoldür; Mem û Zîn''deki dil ve kimlik vurgusu bu düşüncenin temelidir.','tr'),
  ('ba2759a3-1e8f-58a5-9b65-7c675166802a','offline_9552','explanation_tr','"Masture Erdelan": tarihte divan yazmış ilk Kürt kadın tarihçi ve şair.','Mestûre Erdelan (1805–1848), Erdelan Beyliği''nin tarihini yazdı ve şiirlerini divanda topladı; ilk Kürt kadın tarihçi olarak anılır.','tr'),
  ('1512d71a-288b-5a23-80db-3b6968d2c79c','offline_9594','explanation_tr','"Nûbihara Biçûkan": Ehmedê Xanî tarafından yazılan ilk Kürtçe sözlük.','Nûbihara Biçûkan, Ehmedê Xanî''nin çocukların Arapça öğrenmesi için yazdığı manzum Arapça–Kürtçe sözlüktür; sözcükler ezberlenecek beyitler hâlinde verilir.','tr'),
  ('421bf996-e228-5b7e-b029-32378213f3e5','offline_9625','explanation_tr','"Osman Sabri": modern Kürt hikayeciliğinin kurucu isimlerinden.','Osman Sebrî (1905–1993), Hawar çevresinde yetişen yazar ve şairdir; modern Kürt öykücülüğünün kurucu adlarından sayılır.','tr'),
  ('8d92ec5b-8537-5cf0-99ad-fda48ab582e3','offline_9724','explanation_tr','"Hawar Ekolü": Kürt aydınlanmasını ve Latin alfabesini yayan edebi akım.','Hawar Ekolü, 1930–40''larda Bedirxan kardeşler çevresinde gelişti; Latin harfli Kurmancı yazı dilini ve Kürt aydınlanmasını yaydı.','tr'),
  ('c50304aa-5a2e-573f-b066-16598ca81a59','offline_9778','explanation_tr','"Nalî": Soranice klasik şiirin Baban okulunun başlıca adlarından divan şairi.','Nalî, 19. yüzyılda Baban beyliği döneminde Soranice yazan divan şairidir; Soranî klasik şiirin kurucu adlarından sayılır.','tr'),
  ('4343de02-d742-5b98-81a5-a309e00d0d0f','offline_10074','explanation_tr','"Dîwana Melayê Cizîrî": mistik aşk ve felsefe içeren meşhur şiir divanı.','Melayê Cizîrî''nin divanı tasavvufi aşkı ve felsefi düşünceyi işler; klasik Kurmancî şiirin en çok okunan eserlerindendir.','tr'),
  ('b6180e9e-1460-56fd-b07f-409fcd93dc3c','offline_10314','explanation_tr','"serhad ezgileri": Kars, Ağrı ve Van yöresine özgü lirik müzik tarzı.','Serhad ezgileri Kars, Ağrı ve Van yöresinden gelir; uzun soluklu, lirik dengbêj söyleyişleriyle bilinir.','tr'),
  ('11a79256-9ebb-5b2a-8cf5-10c39409d74b','offline_10320','explanation_tr','"dengbêjlik okulu": usta-çırak ilişkisiyle yürüyen müzikal aktarım.','Dengbêjlik usta-çırak ilişkisiyle öğrenilir: genç dengbêj ustasını dinleyerek kilamları ezberler ve onun söyleyişini sürdürür.','tr'),
  ('65970ee9-2dfb-524e-b130-61cff68f505f','offline_10379','explanation_tr','"makam": Türk ve Kürt müziğinde ezgisel yapıyı belirleyen sistem.','Makam, ezginin hangi seslerden kurulacağını ve nasıl ilerleyeceğini belirleyen dizi ve kurallar sistemidir; ritmi değil ezgiyi düzenler.','tr'),
  ('e7333f15-0ae5-594e-b3be-366230238b4b','offline_10423','explanation_tr','"tembûr": Yarsan/Ehl-i Hak geleneğinde kutsal sayılan telli saz.','Tembûr uzun saplı telli bir sazdır; Yarsan (Ehl-i Hak) inancında kutsal sayılır ve cem törenlerinde çalınır.','tr'),
  ('5840fb72-4df1-5971-9170-8c40a337bf2b','offline_10480','explanation_tr','"botan ezgileri": Şırnak ve Cizre yöresinin ritmik ve makamsal müziği.','Botan ezgileri Şırnak ve Cizre yöresine aittir; ritmik ve makamsal yapısıyla öteki yöre tarzlarından ayrılır.','tr'),
  ('74f436dc-cd10-53f9-9655-c003f190d9dc','offline_10498','explanation_tr','"Koma Amed": 90''larda Kürt müziğinde devrim yapan alternatif müzik grubu.','Koma Amed, Kürt müziğine modern çalgılar ve yeni düzenlemeler getiren alternatif bir müzik grubudur.','tr'),
  ('199ad51d-6132-58a8-8436-49c6bedef930','offline_10566','explanation_tr','"nota": müziği kağıda dökmek için kullanılan evrensel işaretler.','Nota, seslerin yüksekliğini ve süresini yazıyla gösteren işaret sistemidir; böylece bir ezgi kâğıttan okunup çalınabilir.','tr'),
  ('4efa354e-b0f0-5425-b4f5-085c3713c393','offline_10572','explanation_tr','"Hasan Cizrawî": erken dönem Kürt müziği kayıtlarını yapan dengbêj.','Hesen Cizrawî, Bağdat Radyosu''nun Kürtçe yayınlarında yıllarca kilam söyleyen Cizreli bir dengbêjdir.','tr'),
  ('1d460377-37ec-5152-baa9-9436757d7e35','offline_10813','explanation_tr','"şabaş geleneği": müzisyenlere para atarak taltif etme adeti.','Şabaş, düğünlerde para ya da armağan verme geleneğidir; birçok yörede çalgıcılara verilen bahşişi de kapsar.','tr'),
  ('59bfeddd-0c33-5014-9534-3dfbbe134c72','offline_10926','explanation_tr','"Mihemed Şêxo": Kürt halkının ulusal duygularını seslendiren ozan.','Mihemed Şêxo (1948–1989), Rojava kökenli bir sanatçıdır; tembûrla söylediği ulusal ve toplumsal şarkılarla tanınır.','tr'),
  ('40ee687a-2280-566d-b7c9-d3659cf5cde1','offline_11068','explanation_tr','"behedînî ezgileri": Duhok ve Zaho yöresine has müzikal tarz.','Behdînî ezgileri Duhok ve Zaho çevresine (Behdînan) özgüdür; yöre ağzı ve kendine has ritimleriyle tanınır.','tr'),
  ('c48de691-6c34-537d-8c95-93c5df996523','offline_11125','explanation_tr','"Şivan Perwer": Kürt müziğini uluslararası sahnelere taşıyan, sürgünde de üretmeyi sürdüren sanatçı.','Şivan Perwer, 1970''lerden beri Avrupa başta olmak üzere dünya sahnelerinde Kürtçe şarkılar söyledi; uzun yıllar sürgünde üretmeyi sürdürdü.','tr'),
  ('1a33d5cf-9c5a-5047-9562-e1ef5f9bc716','offline_11136','explanation_tr','"ritim": müziğin temelini oluşturan düzenli vuruşlar.','Ritim, müzikte seslerin ve susların süre ve vurgu bakımından düzenlenmesidir; ezgiden farklı olarak seslerin yüksekliğini değil zamanlamasını belirler.','tr'),
  ('9b118378-3bf5-58d1-8a3f-aaffb4706c67','offline_11294','explanation_tr','"erbane": halk müziğinde yaygın olarak çalınan zilli tef.','Erbane, kasnağına zil ya da halka takılan büyük bir teftir; dinî meclislerde ve halk müziğinde ritim için çalınır.','tr'),
  ('8b73c0ae-af0a-598f-9776-02fa29944ee7','offline_12899','explanation_tr','"ademi merkeziyetçilik": yetkinin merkezden yerel birimlere dağıtılması.','Ademi merkeziyetçilikte karar yetkisinin bir bölümü merkezî yönetimden il, bölge ve belediyeler gibi yerel birimlere aktarılır.','tr'),
  ('e953efd8-6f54-5ea2-a72d-d61c0ece7c4a','offline_13040','explanation_tr','"azınlık hakları": çoğunluktan farklı grupların korunması.','Azınlık hakları, sayıca az olan grupların dilini, dinini ve kültürünü çoğunluk karşısında korumayı amaçlar.','tr'),
  ('12ffd15e-531d-5f5d-9ae0-3031d7c4fd55','offline_13122','explanation_tr','"barış hakkı": toplumun savaşsız yaşama dair evrensel hakkı.','Barış hakkı, bireylerin ve toplumların savaş ve şiddet tehdidi olmadan yaşama hakkıdır; insan haklarının "dayanışma hakları" kuşağında sayılır.','tr'),
  ('51cd0509-a55f-543e-a98b-d1f1d69a354a','offline_13252','explanation_tr','"insan hakları": herkesin doğuştan sahip olduğu evrensel haklar.','İnsan hakları, kimsenin bağışlamasına bağlı olmadan her insanın doğuştan sahip olduğu evrensel haklardır; 1948 İnsan Hakları Evrensel Beyannamesi bunları sayar.','tr'),
  ('26f36d38-a675-5830-99bf-b37e4434dc00','offline_13729','explanation_tr','"müzakere": sorunları diyalog yoluyla çözme yöntemi.','Müzakere, tarafların sorunları güç kullanmadan karşılıklı görüşme ve uzlaşmayla çözmeye çalışmasıdır.','tr'),
  ('c7eb5be1-0bb8-5f79-841a-d4eb05e710ce','offline_13745','explanation_tr','"çoğulculuk": farklı kimlik ve inançların eşit kabulü.','Çoğulculuk, toplumdaki farklı kimlik, inanç ve görüşlerin bir arada ve eşit biçimde var olabilmesini savunur.','tr'),
  ('4374f3ad-1c34-5e95-b4bc-408be1df17d9','offline_curated_20001','explanation_tr','"ergatîf" şu anlama gelir: geçişli fiillerin öznesini geçmiş zamanda bükümlü gösteren dilbilgisi yapısı.','Ergatif yapıda geçişli fiilin öznesi geçmiş zamanda bükümlü olur: "Min nan xwar" (Ben ekmek yedim) cümlesinde özne "ez" değil "min"dir.','tr'),
  ('9acbc43f-b9d9-585e-8e54-eae85a2dfde6','offline_curated_20026','explanation_tr','"tewandin" şu anlama gelir: ad ya da zamirlerin cümledeki rolüne göre ek değiştirmesi.','Tewandin, ad ve zamirlerin cümledeki görevine göre biçim değiştirmesidir: "ez" bükümle "min", "jin" ise "jinê" olur.','tr'),
  ('f9c06f28-dbe6-5d78-97e4-02d4b5949e98','offline_curated_20051','explanation_tr','"ezafe" şu anlama gelir: adları birbirine bağlayan dişil (a) ve eril (ê) tamlama ilişkisi.','Ezafe, adı kendisinden sonra gelen sözcüğe bağlar: dişil adlarda "-a" (mala min = benim evim), eril adlarda "-ê" (bavê min = benim babam).','tr'),
  ('38fbf109-6c46-570f-83ed-9e1125dc2beb','offline_curated_20076','explanation_tr','"cînavkên tewandî" şu anlama gelir: büküm (tewandin) almış "min, te, wî, wê, me, we, wan" gibi zamirler.','Bükümlü zamirler (min, te, wî, wê, me, we, wan) şimdiki zamanlı geçişli cümlede nesne, geçmiş zamanlı geçişli cümlede özne olur: "Ez wî dibînim" (Onu görüyorum), "Min ew dît" (Onu gördüm).','tr'),
  ('2b5cf310-88bb-5a54-a88b-d65c756d14bd','offline_curated_20126','explanation_tr','"lêkera gerguhêz" şu anlama gelir: anlamını tamamlamak için bükümlü nesneye ihtiyaç duyan fiiller.','Geçişli fiiller nesne alabilir: "xwarin" (yemek) ile neyin yendiği söylenebilir ("Ez nan dixwim"); "hatin" (gelmek) ise geçişsizdir ve nesne almaz.','tr'),
  ('b3d2fac6-10e1-5df6-8cd6-7bcf72f3ac9c','offline_curated_20151','explanation_tr','"rênivîsa Hawarê" şu anlama gelir: Celadet Bedirxan''ın hazırladığı Latin harfli Kürt alfabesi sistemi.','Hawar yazımı, Celadet Alî Bedirxan''ın 1932''de Hawar dergisiyle yaydığı 31 harfli Latin Kurmancî alfabesidir; bugün yaygın biçimde kullanılan yazımdır.','tr'),
  ('3a4274cb-5e1a-5101-b418-3c3ac192d9e1','offline_curated_20176','explanation_tr','"cînavkên kesane" şu anlama gelir: kişiler için kullanılan "ez, tu, ew, em, hûn, ew" gibi göstericiler.','Kişi zamirleri (ez, tu, ew, em, hûn, ew) bükümsüz yalın hâldir; şimdiki zamanda özne olarak kullanılır: "Ez diçim" (Gidiyorum).','tr'),
  ('561527f4-5679-5fe3-83c2-ff90010d2b87','offline_curated_20201','explanation_tr','"dema borî ya dûr" şu anlama gelir: çok uzak bir geçmişte olan eylemi gösteren fiil yapısı.','Uzak geçmiş (dema borî ya dûr), geçmişteki bir eylemden önce tamamlanmış eylemi anlatır: "Ez hatibûm" (Gelmiştim), "Min xwaribû" (Yemiştim).','tr'),
  ('508123b7-3a59-5da3-97d5-4e5567c80bc4','offline_curated_20226','explanation_tr','"paşgirên tewandinê" şu anlama gelir: adların bükümünde yer alan "-î, -ê, -an" gibi ekler.','Büküm ekleri adın cümledeki görevine göre eklenir: eril tekilde "-î" (mêrî), dişil tekilde "-ê" (jinê), çoğulda "-an" (zarokan).','tr'),
  ('d5d1dc8d-428e-5d48-865f-1693c1ce35ed','offline_curated_20251','explanation_tr','"Melayê Cizîrî" şu anlama gelir: felsefî ve tasavvufî divanıyla tanınan büyük klasik şair.','Melayê Cizîrî (16.–17. yy), divanında tasavvufi aşkı ve felsefi düşünceyi işleyen klasik Kurmancî şairidir; Cizre''de yaşamıştır.','tr'),
  ('cec40864-20c2-5066-90b8-c844e70fe42a','offline_curated_20276','explanation_tr','"Feqiyê Teyran" şu anlama gelir: "Şêx Sen''an" eseri ve kuşlarla konuşmasıyla tanınan klasik şair.','Feqiyê Teyran, "teyr" (kuş) sözcüğünden gelen adını kuşlarla konuştuğu söylencesinden alır; Şêx Sen''an manzum hikâyesiyle tanınır.','tr'),
  ('89461275-3ebd-58bb-b783-6b4bc39f993b','offline_curated_20326','explanation_tr','"Melayê Bateyî" şu anlama gelir: ilk Kürt Mevlidini Kurmancî lehçesinde yazan şair.','Melayê Bateyî, Kurmancî yazdığı Mewlûda Kurdî ile tanınır; bu mevlit bugün de dinî toplantılarda okunur. Yaşadığı dönem konusunda farklı görüşler vardır.','tr'),
  ('86d45d6f-a690-58df-93ed-b0557ab297a5','offline_curated_20375','explanation_tr','"Cegerxwîn" şu anlama gelir: modern Kürt şiirini yeni bir aşamaya taşıyan devrimci ve toplumcu şair.','Cegerxwîn, klasik biçimleri kullanmakla birlikte şiirin konusunu tasavvuftan halkın yoksulluğuna, haklarına ve özgürlüğüne çevirdi.','tr'),
  ('3bad7ce2-4c0c-58e9-8dc9-06b08c8a0808','offline_curated_20426','explanation_tr','"Mehmed Uzun" şu anlama gelir: derin ve edebî diliyle Kürt romanında devrim yapan modern Kürt romancısı.','Mehmed Uzun (1953–2007), Siya Evînê ve Bîra Qederê gibi romanlarıyla Kurmancî romanı edebî dil ve derinlik açısından yeni bir düzeye taşıdı.','tr'),
  ('e2383ed2-23aa-56f5-b7ce-60e7a686af4c','offline_curated_20451','explanation_tr','"şevbêrkên wêjeyî" şu anlama gelir: klasik ve modern şiir ile hikâyelerin okunduğu gece toplantıları.','Edebî şevbêrkler, kış gecelerinde toplanılıp klasik ve modern şiirlerin, hikâyelerin okunduğu sohbet toplantılarıdır; sözlü edebiyatın aktarıldığı yerlerdir.','tr'),
  ('d8c3d439-b1cc-5988-8d8b-368611243b0c','offline_curated_20476','explanation_tr','"Helbesta Azad" şu anlama gelir: ölçüsüz ve kafiyesiz, ağırlığını sözcüğe veren modern şiir yöntemi.','Serbest şiir (Helbesta Azad) ölçü ve kafiye zorunluluğunu kaldırır; kafiye kullanılabilir ama şart değildir, anlam ve etki sözcük seçimiyle kurulur.','tr'),
  ('e0a361e9-03d5-53f1-8590-b2d2b4226d66','offline_curated_20501','explanation_tr','"Împaratoriya Medî" şu anlama gelir: bazı Kürt tarih anlatılarında atalara bağlanan, Zagros dağlarındaki antik güç.','Medler, MÖ 7.–6. yüzyılda Zagros merkezli bir imparatorluk kurdu; bazı Kürt tarih anlatıları Kürtlerin kökenini Medlere bağlar.','tr'),
  ('cf1d8cee-f9c5-5683-bb7e-8683c546db06','offline_curated_20526','explanation_tr','"Dewleta Merwaniyan" şu anlama gelir: merkezi Amed ve çevresi olan ortaçağ Kürt hanedanı.','Mervanîler, 10. yüzyılın sonundan 1085''e kadar Amed ve Farqîn (Silvan) çevresinde hüküm süren ortaçağ Kürt hanedanıdır.','tr'),
  ('566fc3c0-6b02-5384-9876-6ec99961c911','offline_curated_20625','explanation_tr','"Selaheddînê Eyûbî" şu anlama gelir: Kudüs''ü Haçlılardan geri alan ve Eyyubi hanedanını kuran büyük Kürt önder.','Kürt kökenli Selahaddin Eyyubi, 1171''de Eyyubi yönetiminin temelini attı; 1187''de Hıttin zaferinin ardından Kudüs''ü Haçlılardan aldı.','tr'),
  ('a97da665-c2f8-5802-a724-f3b2b8928578','offline_curated_20679','explanation_tr','"Rojnameya Kurdistan": 1898''de Kahire''de Mîqdat Mîdhad Bedirxan tarafından çıkarılan ilk Kürtçe gazete.','Kurdistan gazetesi 22 Nisan 1898''de Kahire''de Mikdat Mithat Bedirxan tarafından yayımlandı; ilk Kürtçe gazete olduğu için bu tarih Kürt basın günü sayılır.','tr'),
  ('11637dbd-8ca6-541f-b8b6-783aaa304c72','offline_curated_20701','explanation_tr','"Mîrgeha Erdelanê" şu anlama gelir: merkezi Sine olan, doğudaki kadim bir Kürt beyliği.','Erdelan Beyliği''nin merkezi Sine (Senendec) idi; Doğu Kürdistan''da yüzyıllarca süren bir beylikti ve Mestûre Erdelan bu beyliğin tarihini yazdı.','tr'),
  ('b6d66019-4aad-59dd-b116-a42bef42c3a4','offline_curated_20750','explanation_tr','"çiyayên Zagrosê" şu anlama gelir: Kürtlerin ülkesinin doğal sınırını oluşturan büyük ve sarp sıradağlar.','Zagros Dağları kuzeybatı–güneydoğu doğrultusunda uzanan sarp bir sıradağdır; Kürt coğrafyasının doğal sınırlarından ve omurgasından biridir.','tr'),
  ('1e1d5a70-f478-502d-9121-5d4f129a573a','offline_curated_20826','explanation_tr','"Çiyayê Cûdî" şu anlama gelir: inanışa göre Nuh Peygamber''in gemisinin üzerine oturduğu kutsal dağ.','Cudi Dağı Şırnak''tadır; İslami gelenekte ve bazı eski kaynaklarda Nuh''un gemisinin oturduğu yer olarak anılır.','tr'),
  ('13f09861-251b-5ac7-8edd-b8c74a5c17a1','offline_curated_20851','explanation_tr','"Girê Mirazan" şu anlama gelir: Riha (Urfa) yakınlarındaki, insanlığın en eski tapınak yeri.','Göbeklitepe (Girê Mirazan), Urfa yakınında yaklaşık 11.600 yıl öncesine uzanan anıtsal yapılarıyla bilinen Neolitik bir alandır; yapılar törensel işlevlerle ilişkilendirilir ve bilinen en eski tapınak yapılarından sayılır.','tr'),
  ('34705932-2632-59da-a12f-aca9f2087b8a','offline_curated_20901','explanation_tr','"Çiyayê Sîpanê" şu anlama gelir: Van Gölü''nün kuzeyindeki yüksek ve karlı volkanik dağ.','Süphan Dağı (Çiyayê Sîpanê), Van Gölü''nün kuzey kıyısında yükselen sönmüş bir volkandır; Türkiye''nin en yüksek dağlarındandır.','tr'),
  ('f97a2f0c-70ac-53db-9565-7d29204ca7ce','offline_curated_20926','explanation_tr','"Geliyê Zapê" şu anlama gelir: coşkun Zap suyunun güneye doğru aktığı derin ve dar vadi.','Zap Vadisi (Geliyê Zapê), Hakkari dağlarından güneye akan Büyük Zap''ın açtığı derin ve dar vadidir; Zap sonunda Dicle''ye karışır.','tr'),
  ('bac807de-18f9-55ab-9d60-d74dbf95b631','offline_curated_20951','explanation_tr','"Heskîf" şu anlama gelir: Dicle kıyısındaki, eşsiz mağaralarıyla bilinen kadim tarihî kent.','Heskîf (Hasankeyf), Dicle kıyısında kayalara oyulmuş binlerce mağara konutuyla bilinir; eski kentin büyük bölümü Ilısu Barajı suları altında kaldı.','tr'),
  ('43bcb411-91b7-5c77-aeb3-b030a5ec2691','offline_curated_20976','explanation_tr','"Qerejdax" şu anlama gelir: Amed ovasını Riha ovasından ayıran bazaltik volkanik dağ.','Karacadağ (Qerejdax), Diyarbakır ile Urfa ovaları arasında uzanan geniş bir kalkan volkanıdır; bazalt lavları iki ovayı birbirinden ayırır.','tr'),
  ('ea1f3a69-b8c9-5d3a-8671-2b838c14da19','offline_curated_21001','explanation_tr','"Sazîbûna Dengbêjiyê" şu anlama gelir: dengbêjlerin stran ve kilamlarıyla yürüyen, dili ve tarihi koruyan kale.','Dengbêjlik, yazının yaygın olmadığı dönemlerde tarihi, savaşları ve aşkları kilamlarla kuşaktan kuşağa aktararak dili ve hafızayı korudu.','tr'),
  ('c2471c74-2b7e-560a-a16b-2076a08b536f','offline_curated_21076','explanation_tr','"Govenda Kurdî" şu anlama gelir: el ele tutuşarak ve dayanışma ruhuyla oynanan toplu halk dansı.','Govend, katılanların el ele ya da omuz omuza tutuşup halka veya sıra hâlinde oynadığı toplu halk dansıdır.','tr'),
  ('278b149d-3a62-5cdd-aecd-02abffe46efd','offline_curated_21101','explanation_tr','"çanda koçeriyê" şu anlama gelir: yayla ve germiyan arasındaki, Kürt kültürünü zenginleştiren kadim yaşam biçimi.','Göçerlikte sürüler yazın serin yaylalara (zozan), kışın ılık alçak yerlere (germiyan) götürülür; yaşam bu mevsimlik döngüye göre kurulur.','tr'),
  ('63827b58-2d46-5781-9f67-76ca544b1ddd','offline_curated_21176','explanation_tr','"Destana Memê Alan" şu anlama gelir: Xanî''nin Mem û Zîn''inin temelini oluşturan Kürt ulusal destanı.','Ehmedê Xanî 1692''de yazdığı Mem û Zîn''de sözlü Memê Alan destanından yararlandı ve onu ulusal bir aşk mesnevisine dönüştürdü.','tr'),
  ('bcb4471c-f216-5c5b-b2d3-6b66c383f370','offline_curated_21200','explanation_tr','"hewran" şu anlama gelir: diğer giysilerin üstüne giyilen uzun üstlük/aba.','Hewran, öteki giysilerin üstüne giyilen uzun dış giysidir; en üst kat olarak giyilir.','tr'),
  ('80e0767c-3872-55cb-9f40-e9fafa8be3b6','offline_curated_21226','explanation_tr','"şevbêrk" şu anlama gelir: halk masalları ve bilmecelerin anlatıldığı kış gecesi toplantıları.','Şevbêrk, uzun kış gecelerinde bir evde toplanılıp masal, bilmece ve kilamlarla vakit geçirilen toplantıdır.','tr'),
  ('dee39536-39d7-5f58-9905-c487d6f39943','offline_curated_21251','explanation_tr','"tembûr" şu anlama gelir: özellikle dinî meclislerde çalınan, Yarsan/Ehl-i Hak geleneğinde kutsal sayılan telli çalgı.','Tembûr uzun saplı telli bir sazdır; Yarsan (Ehl-i Hak) inancında kutsal sayılır ve cem törenlerinde çalınır.','tr'),
  ('b9ccc63f-ac26-59b8-b4d8-625105ec4190','offline_curated_21276','explanation_tr','"erbane" şu anlama gelir: Kürt dinî ve halk müziğinde önemli yeri olan zilli vurmalı çalgı.','Erbane, kasnağına zil ya da halka takılan büyük bir teftir; tekke ve dinî meclislerde zikre ve halk müziğinde ritme eşlik eder.','tr'),
  ('a7cb2c9b-b992-563f-9842-87e1a55ff705','offline_curated_21301','explanation_tr','"bilûr" şu anlama gelir: hüzünlü ve lirik sesiyle bilinen çoban üflemeli çalgısı.','Bilûr, çobanların taşıdığı ağızdan üflemeli kaval türü çalgıdır; yumuşak ve hüzünlü sesiyle tanınır.','tr'),
  ('b9ae7f7e-1b22-598a-9e8a-359e757917e0','offline_curated_21326','explanation_tr','"lîrîka klaman" şu anlama gelir: aşk ve savaş hikâyelerini anlatan dengbêj kilamlarının şiirsel yapısı.','Dengbêj kilamları aşk ve savaş hikâyelerini şiirsel bir dille, tekrarlarla ve uzun ezgili söyleyişle anlatır.','tr'),
  ('3d29e580-9e55-56fc-b738-071562af70cf','offline_curated_21351','explanation_tr','"Şakiro" şu anlama gelir: "Dengbêjlerin Şahı" diye bilinen, eşsiz sese sahip büyük dengbêj.','Şakiro (1936–1996), güçlü sesi ve geniş kilam dağarcığıyla dengbêjler arasında "dengbêjlerin şahı" diye anılır.','tr'),
  ('d72e8f29-7c93-5925-81c2-92e35fccad60','offline_curated_21376','explanation_tr','"Hasan Cizrawî" şu anlama gelir: Botan yöresinin kilamlarını kaydeden, klasik Kurmancî müziğinin direklerinden biri.','Hesen Cizrawî, Bağdat Radyosu''nun Kürtçe yayınlarında söylediği Botan kilamlarıyla tanınan Cizreli bir dengbêjdir.','tr'),
  ('f0b35b33-3d94-54a1-a028-e7ca04b782b2','offline_curated_21401','explanation_tr','"Meryem Xan" şu anlama gelir: sesini plağa kaydeden ilk Kürt kadın şarkıcı.','Meryem Xan (1904–1949), 1920''lerde ve 1930''larda plak dolduran ilk Kürt kadın şarkıcılardandır.','tr'),
  ('8d89bae8-ac07-5b59-9ac8-b1dabdf2c113','offline_curated_21451','explanation_tr','"lawik" şu anlama gelir: çoğunlukla aşk ve hasret üzerine söylenen lirik dengbêjlik kilamı.','Lawik, dengbêjlik geleneğinde çoğunlukla aşkı, hasreti ve ayrılığı işleyen lirik kilam türüdür.','tr'),
  ('bb4d417e-241e-504f-ab15-882fe1ddb986','offline_curated_21475','explanation_tr','"heyran" şu anlama gelir: özellikle kadınların söylediği Serhat yöresi aşk kilamları.','Heyranok (heyran), Serhed yöresinde çoğunlukla kadınların söylediği, sevdiğine seslenen aşk kilamlarıdır.','tr'),
  ('4871a5b2-2479-536f-a069-d310f26bb12f','offline_curated_21601','explanation_tr','"ademi-merkeziyet" şu anlama gelir: iktidarın merkezden bölgelere ve özerk yönetimlere dağıtılması.','Ademi merkeziyette yetki merkezî yönetimde toplanmaz; bölgelere ve yerel yönetimlere dağıtılır.','tr'),
  ('523101c4-385b-54a2-863e-4a8af327459f','offline_curated_21651','explanation_tr','"pirrengî" şu anlama gelir: toplumdaki bütün farklı kimliklerin korunması ve kabul edilmesi ilkesi.','Pirrengî (çoğulculuk), toplumdaki farklı kimliklerin bir arada var olmasını ve eşit biçimde tanınmasını savunan ilkedir.','tr'),
  ('b9f95b18-db36-585c-a9b7-0c9be820e5c3','offline_curated_21676','explanation_tr','"demokrasiya rasterast" şu anlama gelir: halkın temsilciler olmadan karar verdiği yönetim biçimi.','Doğrudan demokraside halk kararları temsilci seçmeden kendisi alır; meclislerde ya da halk oylamalarında doğrudan oy kullanır.','tr'),
  ('872e482d-52cc-5bb4-a208-d2f4eb6d0737','offline_tf_siy_0031','explanation_tr','Evet. Aynı alandan bir başka kavram: "dadgehkirina dadperwer" şu anlama gelir: herkesin açık, tarafsız ve makul sürede yargılanma hakkı.','Doğru. Cinsiyet kotası (kotaya zayendî), kurumlarda ve seçilmiş organlarda kadınların belirli bir orandan az temsil edilmemesi için asgari bir pay belirlenmesidir.','tr'),
  ('f4e67d62-aea8-56a1-88e8-878db7b034d9','ds_cografya_0199','explanation_tr','Koordinat ağı (graticule), haritada enlem ve boylamları gösteren çizgilerdir. İzolin çizgisi ise yüksekliği gösterir.','Koordinat ağı (graticule), haritada enlem (paralel) ve boylam (meridyen) çizgilerinin oluşturduğu ağdır. İzolin ise eş değerli noktaları birleştiren çizgidir; eş yükselti eğrisi bunun yükseklik için kullanılan türüdür.','tr'),
  ('97a7c8aa-a36e-5e01-9225-ea3c1c6ea478','cinema_0005','explanation_tr','Vitaphone sistemiyle konuşma ve şarkı görüntüyle eşzamanlı verildi; bu, sessiz dönemin birkaç yıl içinde kapanmasına yol açtı. Renkli süreç ve uzun metraj animasyon yenilikleri 1930''ların sonunu bekledi.','Vitaphone sistemiyle şarkılar ve bazı konuşmalar görüntüyle eşzamanlı verildi. Ses ile görüntünün eşzamanlı verilmesi, sessiz filmden sesli filme geçişi hızlandırdı.','tr'),
  ('da5dbcb8-c9de-5ce7-8a88-af9a272a9675','ders_2026_10_01_0055','explanation_tr','"Dilşad" sevinç ve neşedir.','"Dilşad" sevinçli, neşeli demektir; "dil" (gönül) ve "şad" (sevinçli) sözcüklerinden oluşur. "Xemgîn" ise üzgün demektir.','tr'),
  ('c1f8e390-1284-5240-9e23-1f3e3e35c12e','ds_cografya_0205','explanation_tr','İç göç, bir ülke içinde, örneğin köyden şehre göç etmek anlamına gelir. Dış göç başka bir ülkeye gitmektir; geçici ve döngüsel göç ise geçicidir.','İç göç, bir ülkenin sınırları içinde yapılan göçtür; köyden şehre ve şehirler arası göç bunun örnekleridir. Dış göç başka bir ülkeye yapılır; geçici ve döngüsel göç ise belirli bir süre ya da mevsim için yapılır ve kalıcı yerleşme amacı taşımaz.','tr'),
  ('c01560a2-2d59-554b-91c0-28ff7cc365ed','offline_tf_siy_0018','explanation_tr','Hayır — bu tanım "muxalefeta civakî" kavramına ait; "muxalefeta demokratîk", iktidarı silaha başvurmadan, hukuk içinde eleştirmedir.','Yanlış. Demokratik muhalefeti yalnız partiler değil; sivil toplum kuruluşları, sendikalar ve toplumsal hareketler de barışçıl ve hukuki yollarla yürütebilir.','tr'),
  ('23f9a5f4-9182-5e0c-b470-8f0390cb2489','ds_cografya_0284','explanation_tr','Karacadağ''ın bazaltik lavlarından ayrışan topraklar demir, fosfor ve potasyum yönünden zengin olup taş temizliği sonrası çok verimlidir.','Karacadağ bazaltından gelişen topraklar, ana materyalden gelen demir ve magnezyum içeren mineralleri barındırır; tarımsal verimlilik ayrıca toprak gelişimi ve koşullara bağlıdır.','tr'),
  ('44ab0464-2fa5-54f4-b77d-436a50983824','ds_cografya_0248','option_b','Hêzar gola cemedî ye, Nemrûd gola kembera karstîk e','Hêzar gola setê ya volkanîk e, Nemrûd gola tektonîk a daketî ye','ku'),
  ('44ab0464-2fa5-54f4-b77d-436a50983824','ds_cografya_0248','option_c','Hêzar gola setê ya çem e, Nemrûd gola tektonîk a kûr e','Hêzar gola karstîk a helînê ye, Nemrûd gola setê ya volkanîk e','ku'),
  ('44ab0464-2fa5-54f4-b77d-436a50983824','ds_cografya_0248','option_d','Hêzar gola çêkirî ye, Nemrûd gola sirûştî ya aluvyal e','Hêzar gola setê ya şemitînê ye, Nemrûd gola kolandina cemedê ye','ku'),
  ('4b0b208e-26f7-5abf-b54a-e948a2166334','ds_cografya_0249','option_a','Rêjeya baranê ji ya hemû herêmên cîran gelekî zêdetir bûye','Aluvyonên Çemê Bedlîsê bi demê re derketina golê bi temamî girtiye','ku'),
  ('4b0b208e-26f7-5abf-b54a-e948a2166334','ds_cografya_0249','option_b','Çemê Dîcleyê ava xwe bi temamî rijandiye nav vê newalê','Lavên Sîpanê herikîna derve ya hewzeyê birriye û goleke girtî çêkiriye','ku'),
  ('4b0b208e-26f7-5abf-b54a-e948a2166334','ds_cografya_0249','option_c','Tektonîka Zagrosê ava deryayê rasterast kişandiye nav golê','Çemê Muradê rêya xwe guhertiye û ava kaniyên sodavî aniye golê','ku'),
  ('72fb90c4-f869-5e7c-86ff-f7680e97fad3','ds_cografya_0252','option_a','Gola Urmiyeyê ya şor','Gola Urmiyeyê (hewzeya girtî)','ku'),
  ('72fb90c4-f869-5e7c-86ff-f7680e97fad3','ds_cografya_0252','option_b','Deryaya Navîn (Spî)','Gola Aralê (hewzeya girtî)','ku'),
  ('72fb90c4-f869-5e7c-86ff-f7680e97fad3','ds_cografya_0252','option_c','Kendava Farsê ya germ','Kendava Farsê (hewzeya deryayî)','ku'),
  ('b270471d-1d13-5347-a1f2-e63d60fb235f','ds_cografya_0253','option_a','Ji ber ku herêma herî nizm a ji bo çandiniya birincê bû','Ji bo çandiniya aluvyonî di nîvê deşta lehiyê de cih girtin','ku'),
  ('b270471d-1d13-5347-a1f2-e63d60fb235f','ds_cografya_0253','option_c','Ji bo dûrketina ji hemû rêyên bazirganiyê yên herêmî','Sûdwergirtina ji bendereke xwezayî ya fireh û kûr a guncaw bo veguhastina çemî','ku'),
  ('b270471d-1d13-5347-a1f2-e63d60fb235f','ds_cografya_0253','option_d','Ji ber ku li ser xeta herikîna lavên germ ên nû bû','Ji bo parastina ji bayên zivistanê li cihê herî nizm ê newalê cih girtin','ku'),
  ('427bf48d-0bd5-5427-bbf0-cae3169704b2','ds_cografya_0255','option_a','Ji bo diyarkirina rêyên balafiran bi şêwaza herî kurt','Ji bo nîşandana rêyên pûsûleyê yên deryageran bi xetên rast','ku'),
  ('427bf48d-0bd5-5427-bbf0-cae3169704b2','ds_cografya_0255','option_c','Ji bo mezinkirina welatên Ewropayê li gorî Asyayê','Ji bo rakirina bi temamî ya şêwandina şeklê li herêmên cemseran','ku'),
  ('427bf48d-0bd5-5427-bbf0-cae3169704b2','ds_cografya_0255','option_d','Ji bo hêsankirina sefera deryageran li okyanûsan','Ji bo nîşandana rêyên balafiran ên çembera mezin bi xetên rast','ku'),
  ('0a3cc564-53aa-58a8-9334-e9fe2b812492','ds_cografya_0256','option_a','Arîtmetîk tenê jinan dijmêre, fîzyolojîk tenê karkerên bajêr digire nav xwe','Arîtmetîk nifûsa bajêr, fîzyolojîk nifûsa gundan dihesibîne','ku'),
  ('0a3cc564-53aa-58a8-9334-e9fe2b812492','ds_cografya_0256','option_b','Arîtmetîk li seranserê çolê ye, fîzyolojîk li herêmên berfê tê pîvan','Arîtmetîk li gorî qada çandiniyê ye, fîzyolojîk li gorî tevahiya rûberê ye','ku'),
  ('0a3cc564-53aa-58a8-9334-e9fe2b812492','ds_cografya_0256','option_c','Arîtmetîk nifûsa şevê ye, fîzyolojîk nifûsa rojane ya kar nîşan dide','Arîtmetîk li gorî qadên niştecihbûnê, fîzyolojîk li gorî daristan û çêrgehan e','ku'),
  ('ecefa0a2-894e-539b-a127-e4faae0b4fc9','ds_cografya_0260','option_a','Nebûna çemên mezin li seranserê herêmê','Piraniya herêmê di çalên binê asta deryayê de ye','ku'),
  ('ecefa0a2-894e-539b-a127-e4faae0b4fc9','ds_cografya_0260','option_b','Rûberên qûmî yên ku germê qet nagirin','Çiyayên peravê bi derbasgehên nizm parçe bûne û li ber bandora deryayê vekirî ne','ku'),
  ('ecefa0a2-894e-539b-a127-e4faae0b4fc9','ds_cografya_0260','option_d','Kêmbûna radyasyona tavê di werzê havînê de','Hewaya ku li qeraxên çiyan bilind dibe her tim şiliyê dibe herêmên hundir','ku'),
  ('1667c257-6de2-5076-a539-166921db4ab7','ds_cografya_0263','option_a','Ji bo çêkirina cihên fireh ên ji bo firîna balafiran','Bi lezkirina herikîna avê li ser qeraxê derxistina avê zêde kirin','ku'),
  ('1667c257-6de2-5076-a539-166921db4ab7','ds_cografya_0263','option_c','Ji bo dîtina madenên bin erdê bi awayekî hêsantir','Bi dirêjkirina dema tavê ya axê zû gihîştina berheman misoger kirin','ku'),
  ('1667c257-6de2-5076-a539-166921db4ab7','ds_cografya_0263','option_d','Ji bo parastina gund ji bayên germ ên havînê','Bi xurtkirina gera hewayê zirara qeşayê li riwekan kêm kirin','ku'),
  ('70819ef4-4da6-57ed-85fb-e4b7458f29be','ds_cografya_0264','option_a','Rewşa hewayê tenê ji bo deryayê ye, avhewa tenê ji bo çiyê ye','Rewşa hewayê navîniya demdirêj e, avhewa guherîna rojane ye','ku'),
  ('70819ef4-4da6-57ed-85fb-e4b7458f29be','ds_cografya_0264','option_b','Rewşa hewayê qet naguhere, avhewa her roj diguhere','Rewşa hewayê germahiyê, avhewa jî tenê rêjeya baranê dipîve','ku'),
  ('70819ef4-4da6-57ed-85fb-e4b7458f29be','ds_cografya_0264','option_d','Rewşa hewayê bi piyanoyê tê pîvan, avhewa bi termometreyê','Rewşa hewayê parzemînên mezin, avhewa tenê herêmên biçûk digire','ku'),
  ('27b6bf7d-c4ca-5d31-8e9f-37f1474da3e7','ds_cografya_0265','option_b','Herikîna lavên bazaltî yên sarbûyî','Sarbûn û hilweşîna tunelên lavên bazaltî (volkanîk)','ku'),
  ('27b6bf7d-c4ca-5d31-8e9f-37f1474da3e7','ds_cografya_0265','option_c','Hilweşîna cemedên deryayî li deştan','Kolandina zinaran ji aliyê cemedan ve (cemedî)','ku'),
  ('27b6bf7d-c4ca-5d31-8e9f-37f1474da3e7','ds_cografya_0265','option_d','Kevirbûna qûmên çolê bi bayên xurt','Xwarina zinaran bi qûma ku ba dibe (korazyon)','ku'),
  ('95dcee2a-2f36-5d56-8582-79835dd3ffab','ds_cografya_0266','option_a','Kêmbûna radyasyona tavê ya li seranserê herêmê','Kişandina avê ya zêde ji golê ji bo sarkirina saziyên pîşesaziyê','ku'),
  ('95dcee2a-2f36-5d56-8582-79835dd3ffab','ds_cografya_0266','option_b','Vekirina kanaleke mezin a ber bi Deryaya Spî ve','Qirêjiya kîmyewî ya ji kaniyên madenan ên li dora golê','ku'),
  ('95dcee2a-2f36-5d56-8582-79835dd3ffab','ds_cografya_0266','option_d','Zêdebûna hejmara masîgirên kevneşopî yên li ser golê','Zêdebûna bilez a daxwaza ava vexwarinê ya bajarên li peravê golê','ku'),
  ('89d948c5-c7a7-5f7a-a182-f5312b84ecd6','ds_cografya_0267','option_a','Di nîveka zivistanê ya herî sar de','Di nîveka zivistanê de, mehên herî sar','ku'),
  ('89d948c5-c7a7-5f7a-a182-f5312b84ecd6','ds_cografya_0267','option_c','Di dawiya payîzê ya hişk de','Di mehên pêşîn ên baranî yên payîzê de','ku'),
  ('89d948c5-c7a7-5f7a-a182-f5312b84ecd6','ds_cografya_0267','option_d','Tenê di meha tebaxê ya germ de','Di dawiya havînê de, tebax û îlonê','ku'),
  ('bdcc8022-ab37-5e8c-b2b7-c0ce075ef616','ds_cografya_0269','option_b','Germahiyê kêm dike û baranê zêde dike','Germahiyê kêm dike û şiliyê zêde dike, mij çêdike','ku'),
  ('bdcc8022-ab37-5e8c-b2b7-c0ce075ef616','ds_cografya_0269','option_c','Hewayê dicemidîne û dibe sedema berfê','Germahiyê zêde dike û şiliyê bilind dike, baranê dibarîne','ku'),
  ('bdcc8022-ab37-5e8c-b2b7-c0ce075ef616','ds_cografya_0269','option_d','Ti guhertinekê di hewayê de çênake','Germahiyê wekî xwe dihêle, tenê leza bayê zêde dike','ku'),
  ('ed231b2d-fe9a-5d6e-9551-9651712a17b9','ds_cografya_0270','option_a','Herikîna hêdî ya li ser deştên qûmî yên bê kevir','Zimanên cemedê binê newalê bi şeklê U fireh kiriye û kolaye','ku'),
  ('ed231b2d-fe9a-5d6e-9551-9651712a17b9','ds_cografya_0270','option_c','Çêbûna bendavên xwezayî yên ji qeşayê li ber avê','Çem li deşta fireh bi menderesan rêya xwe ber bi aliyan ve vekiriye','ku'),
  ('ed231b2d-fe9a-5d6e-9551-9651712a17b9','ds_cografya_0270','option_d','Nebûna ti herikîna avê di werzê bihar û havînê de','Herikînên lavê newal tije kiriye û di sarbûnê de qelişîne','ku'),
  ('8884736b-cdfa-5b74-9ce8-8833ca58edce','ds_cografya_0273','option_a','Kêmbûna zexta hewayê ji ber barîna berfê ya li çiyayan','Girseya hewaya sar dadikeve binê deştê û zexta bilind çêdike','ku'),
  ('8884736b-cdfa-5b74-9ce8-8833ca58edce','ds_cografya_0273','option_b','Herikîna sermayê ya ji deryayên bakur ber bi başûr','Bayên şil ên ji çiyayan tên li ser deştê kom dibin û gerdav çêdikin','ku'),
  ('8884736b-cdfa-5b74-9ce8-8833ca58edce','ds_cografya_0273','option_c','Hebûna daristanên pir çirr ên li dora deştê','Hewaya hênik a şevê di nîvro de ber bi erdê ve dadikeve','ku'),
  ('ca7a2945-730f-57b0-a1cd-b36ed09a5136','ds_cografya_0274','option_a','Pembû, birinc û mûz','Pembû, garis û silqa şekir','ku'),
  ('ca7a2945-730f-57b0-a1cd-b36ed09a5136','ds_cografya_0274','option_c','Çay, fistiqên şil û findiq','Birinc, fasûlyeya soyayê û fistiqa erdê','ku'),
  ('ca7a2945-730f-57b0-a1cd-b36ed09a5136','ds_cografya_0274','option_d','Qamîşê şekir û tûtina avî','Kartol, gulberoj û tûtin','ku'),
  ('d28041fc-9626-556d-97aa-df309ad3bcf7','ds_cografya_0275','option_a','Nebûna ti zinar û çiyayan li tevahiya herêmê','Zivistana nerm, guncawbûna bo çandiniya deştê û nêzîkbûna bazarê','ku'),
  ('d28041fc-9626-556d-97aa-df309ad3bcf7','ds_cografya_0275','option_b','Hebûna germahiya zêde ya ji bo çandiniya pembû','Havînên hişk, giyayên kêm û kêmbûna nexweşiyên ajalan','ku'),
  ('d28041fc-9626-556d-97aa-df309ad3bcf7','ds_cografya_0275','option_c','Dûrketina ji hemû çavkaniyên avê yên xwezayî','Zivistana nerm, çêrgehên zivistanê yên fireh û demeke çêrandinê ya dirêj','ku'),
  ('9ddc5840-c0f5-5a3f-b42f-d0a16a80588c','ds_cografya_0276','option_a','Tenê di navbera welatên Ewropayê de bazirganiyê dikin','Bajarên Anatoliya Navîn bi benderên Egeyê û bazarên Anatoliya Rojava ve girêdidin','ku'),
  ('9ddc5840-c0f5-5a3f-b42f-d0a16a80588c','ds_cografya_0276','option_b','Rêya çandiniya pembû ji bo zozanên sar vedikin','Hewzeya Gola Wanê bi peravên Qezwînê yên Kafkasyayê ve girêdidin','ku'),
  ('9ddc5840-c0f5-5a3f-b42f-d0a16a80588c','ds_cografya_0276','option_d','Têkiliya Kendava Farsê bi Okyanûsa Pasîfîk re saz dikin','Deştên başûrê rojhilat bi rêya derbasgehên Torosê bi benderên Deryaya Spî ve girêdidin','ku'),
  ('ea9aefd2-0816-59a8-82cc-5f9b4497e8fa','ds_cografya_0277','option_a','Urmiye ava şêrîn a vexwarinê ye, Wan ava tehl a jehrî ye','Urmiye xwedî ava sodavî ya karbonatî ye, Wan xwedî ava şor a klorûrî ye','ku'),
  ('ea9aefd2-0816-59a8-82cc-5f9b4497e8fa','ds_cografya_0277','option_b','Urmiye bi temamî ji petrolê pêk tê, Wan tenê ava berfê ye','Her du gol jî sodavî û karbonatî ne; tenê kûrahiya wan cuda ye','ku'),
  ('ea9aefd2-0816-59a8-82cc-5f9b4497e8fa','ds_cografya_0277','option_c','Her du gol jî xwedî ava şêrîn a wekhev in û ti şorayî tê de nîne','Urmiye ava tehl a sulfatî ye, Wan ava şêrîn a kêmşor e','ku'),
  ('2643da36-fe95-5dda-8c96-22be4df82306','ds_cografya_0279','option_a','Helîna zinarên kilsî yên mezin di bin ava deryayê de','Platoyên lavê yên ku bi tijîbûna newalan ji lavên volkanîk çêbûne','ku'),
  ('2643da36-fe95-5dda-8c96-22be4df82306','ds_cografya_0279','option_b','Komkirina qûmên çolê ji aliyê bayên xurt ên başûr ve','Deltayên ku bi komkirina aluvyonên çeman çêbûne','ku'),
  ('2643da36-fe95-5dda-8c96-22be4df82306','ds_cografya_0279','option_c','Hilweşîna daran di serdemên qeşayê de li ser newalan','Çalên cemedî yên ku bi kolandina newalan ji aliyê cemedan ve çêbûne','ku'),
  ('aa75cc75-04df-5e27-8310-703ac4407629','ds_cografya_0280','option_b','Herikîna avê bi temamî diguherînin ber bi Deryaya Spî ve','Rêyên çeman fireh dikin û li jêr deştên lehiyê yên nû çêdikin','ku'),
  ('aa75cc75-04df-5e27-8310-703ac4407629','ds_cografya_0280','option_c','Avhewaya tevahiya Mezopotamyayê dikin cemserî û sar','Her sal aluvyonên zêdetir dibin peravên deltayê û peravê ber bi deryayê ve pêş dixin','ku'),
  ('aa75cc75-04df-5e27-8310-703ac4407629','ds_cografya_0280','option_d','Rêjeya barana salane li seranserê çiyayan kêm dikin','Şoriya çeman kêm dikin û zûnkavên deltayê dikin golên şêrîn','ku'),
  ('8c7a33ca-d0ab-5a0e-b171-ea37303e84c4','ds_cografya_0282','option_b','Ji ber ku li serê çiyayan germahiya havînê ji her derê zêdetir e','Bikaranîna axa berdar a binê deştê rasterast wekî baxçeyên xaniyan','ku'),
  ('8c7a33ca-d0ab-5a0e-b171-ea37303e84c4','ds_cografya_0282','option_c','Ji bo gihîştina hêsan a keştiyên deryayî yên bazirganiyê','Li quntarên çiyayan zivistanê qatê berfê ji binê deştê ziravtir e','ku'),
  ('8c7a33ca-d0ab-5a0e-b171-ea37303e84c4','ds_cografya_0282','option_d','Ji bo dûrketina ji hemû çavkaniyên daristanî yên herêmê','Ji bo parastina ji heywanên kovî hilbijartina cihên bilind û zinarî','ku'),
  ('7f30b988-0f46-58bd-9399-ded429c7cf5e','ds_cografya_0283','option_a','Tenê xeta Ekwatorê ya nizm','Derdora Ekwatorê (kembera tropîkal)','ku'),
  ('7f30b988-0f46-58bd-9399-ded429c7cf5e','ds_cografya_0283','option_b','Tenê herêma Cemsera Bakur','Derdora cemseran (hêlîpanên bilind)','ku'),
  ('7f30b988-0f46-58bd-9399-ded429c7cf5e','ds_cografya_0283','option_d','Tenê rûberên okyanûsên kûr','Hemû hêlîpan (xeletî li her derê wekhev e)','ku'),
  ('23f9a5f4-9182-5e0c-b470-8f0390cb2489','ds_cografya_0284','option_b','Tenê ji xwêya spî û kilsa heliyayî pêk tê','Ji aliyê karbonata kalsiyûmê ve ji axên kilsî dewlemendtir e','ku'),
  ('23f9a5f4-9182-5e0c-b470-8f0390cb2489','ds_cografya_0284','option_c','Ti mîneralan di nav xwe de nagire û zû hişk dibe','Ji aliyê madeyên organîk ve pir xizan e, qûmî ye û avê nagire','ku'),
