  ('a9a7a739-a477-553d-a696-3d7e75fae5bd','ds_cand_1179','option_a','Tenê ji bo cejnên neteweyî guhertina bajêr','Xwesteka eşîran ku di demên bacê de ji rêveberiyên bajaran dûr bimînin','ku'),
  ('a9a7a739-a477-553d-a696-3d7e75fae5bd','ds_cand_1179','option_b','Ji bo bazirganiya deryayî ya di navbera dewletan de','Mecbûriya çandina dexlê li zozanan di zivistanê de û dirûna wê li deştê di havînê de','ku'),
  ('a9a7a739-a477-553d-a696-3d7e75fae5bd','ds_cand_1179','option_d','Ji bo xwendina zarokan di dibistanên zivistanê de','Girêdana bi kevneşopiya serdana cihên pîroz a salê du caran','ku'),
  ('2a4de7ab-2c4b-5a94-9045-f9365bfd9281','ds_cand_1180','option_a','Zilamê ku berpirsê ewlehiya konên zozanê ye','Pêşengê şandeya ku di dawetan de bûkê ji mala bavê wê tîne','ku'),
  ('2a4de7ab-2c4b-5a94-9045-f9365bfd9281','ds_cand_1180','option_b','Kesê ku tenê kincên dawetê bi destan didûre','Jina pîr a ku di şînan de dilorîne û şînê bi rê ve dibe','ku'),
