  ('a5a3a752-6996-5e73-a4ac-4f0f54d4d296','ds_cand_1183','option_d','Nexşeya sînorên mîrektiyên kevn ên herêmê','Rêyên karwanan, bazirganî û bêriya welatên dûr','ku'),
  ('32b9ad48-80eb-5238-bafa-3d8ce0576fc7','ds_cand_1185','option_a','Li deştên sar ên Qersê','Li zozanên Qers, Erdexan û Erzeromê','ku'),
  ('32b9ad48-80eb-5238-bafa-3d8ce0576fc7','ds_cand_1185','option_c','Li qiraxa Deryaya Qezwînê','Li gundên çiyayî yên Wan, Colemêrg û Elbakê','ku'),
  ('32b9ad48-80eb-5238-bafa-3d8ce0576fc7','ds_cand_1185','option_d','Li giravên başûrê Deryaya Egeyê','Li derdora Dêrsim, Erzîngan û Elezîzê','ku'),
  ('4882723a-6c58-54d0-aaaa-9aa4abad7539','ds_cand_1186','option_a','Tenê ji bo cezakirina kesên ku nehatine sersaxiyê','Ragihandina li ber civakê ka mîrateya mirî dê ji kê re bimîne','ku'),
