  ('4882723a-6c58-54d0-aaaa-9aa4abad7539','ds_cand_1186','option_c','Pêşbirkek ji bo xelata herî bilind a dengbêjiyê','Diyarkirina rêz û pergala mêvandariya kesên ku tên sersaxiyê','ku'),
  ('fb78d683-7f0b-5009-8a9c-061df77f2021','ds_cand_1187','option_a','Bêrîvan (dotinvan)','Bêrîvan','ku'),
  ('fb78d683-7f0b-5009-8a9c-061df77f2021','ds_cand_1187','option_b','Pêşmerge (şervan)','Birazava','ku'),
  ('fb78d683-7f0b-5009-8a9c-061df77f2021','ds_cand_1187','option_d','Çawîş (cerdevan)','Dengbêj','ku'),
  ('78bb8251-66fd-5328-8a44-441ac38cfbc3','ds_cand_1188','option_a','Giranî tenê bi rûniştî tê lîstin, Şêxanî tenê li ser hespan e','Şêxanî bi gavên giran û seknekê ye, Giranî bileztir û livdar e','ku'),
  ('78bb8251-66fd-5328-8a44-441ac38cfbc3','ds_cand_1188','option_b','Giranî tenê bi jinan e, Şêxanî tenê lîstika zarokan e','Her du jî bi heman rîtmê ne; Giranî di dawetan de, Şêxanî di cejnan de tê lîstin','ku'),
  ('78bb8251-66fd-5328-8a44-441ac38cfbc3','ds_cand_1188','option_c','Giranî ti caran bê def nabe, Şêxanî qet muzîkê naxwaze','Giranî bi tenê tê lîstin, Şêxanî tenê bi cotên du kesî tê lîstin','ku'),
  ('604b70fc-0eb9-5295-a32b-43768578e22e','ds_cand_1189','option_a','Cejna Qurbanê ya Payîzê','Cejna Êzîd (cejna rojiya Kanûnê)','ku'),
  ('604b70fc-0eb9-5295-a32b-43768578e22e','ds_cand_1189','option_c','Cejna Remezanê ya Mezin','Cejna Cemayê (civîna payîzê ya Lalişê)','ku'),
  ('604b70fc-0eb9-5295-a32b-43768578e22e','ds_cand_1189','option_d','Şeva Yeldayê ya Zivistanê','Newroz (cejna biharê ya 21ê Adarê)','ku'),
  ('eb1aca6d-a1b6-5c33-823c-a158dc1a13ab','ds_cand_1191','option_b','Tenê qonaxên dewlemendan ên li navenda bajaran','Cihên civînê yên hevpar ên li qadên gundan ku di cejnan de tên bikaranîn','ku'),
