  ('1cfd5326-1758-5988-ac13-61cdddd4e068','ds_cand_1198','option_d','Hemû cureyên xwendin û nivîsandina bi kurdî qedexe dikir','Hînkirina kurdî tenê bi axaftina rojane re sînordar dibû û wêjeya nivîskî nedihat xwendin','ku'),
  ('793b516a-bec9-5b6a-9d86-51ddb3ff26ed','ds_cand_1200','option_b','Voleybola ser masê','Beyzbol an krîketa îngilîzî','ku'),
  ('793b516a-bec9-5b6a-9d86-51ddb3ff26ed','ds_cand_1200','option_c','Avjenî û melevaniyê','Bocce an bîlardo','ku'),
