  ('c45c2776-23ff-56bf-8462-aa6b3d729533','ds_cand_1202','option_a','Tenê komkirina bacên salane ji bo axayên herêmê','Pîrozkirina dawiya dirûnê û parvekirina zexîreya zivistanê di navbera malbatan de','ku'),
