  ('bd950be5-e5d6-5aed-8704-24641f1f181d','ds_cand_1204','option_d','Tenê ronahiya tavê ya zêde dikişîne nav nivîn û odeyan','Ji ber ku qumaş pir sivik e, kesek dikare di saetekê de hilgire û vegire','ku'),
  ('577a6f3e-8780-51b4-af70-58eb2fd82f05','ds_cand_1205','option_a','Tenê li gorî leza hespê yê ku herî pêşîn hatiye','Li gorî rêza ketina odeyê; yê pêşîn diçe serê odê, yê dawî li ber derî','ku'),
  ('577a6f3e-8780-51b4-af70-58eb2fd82f05','ds_cand_1205','option_b','Tenê li gorî rengê kincên ku li xwe kirine','Li gorî rêzeke ku bi nirxê çek û hespê kesî tê diyarkirin','ku'),
  ('577a6f3e-8780-51b4-af70-58eb2fd82f05','ds_cand_1205','option_d','Li gorî bejna herî dirêj di nav ciwanan de','Li gorî rêzeke ku xwediyê malê her êvar bi pişkê ji nû ve diyar dike','ku'),
  ('afabb6d9-868b-5205-acd3-dba1343a2ffd','ds_cand_1206','option_a','Tenê wekî kincê fermî di dadgehan de tê lixwekirin','Ji ber ku sivik û zirav e, di germa havînê de siyê dide','ku'),
  ('afabb6d9-868b-5205-acd3-dba1343a2ffd','ds_cand_1206','option_c','Tenê di bin avê de ji bo melevaniyê tê bikaranîn','Bi rengên xwe yên geş dihêle ku di hewaya mijdar de şivan ji dûr ve bê dîtin','ku'),
  ('afabb6d9-868b-5205-acd3-dba1343a2ffd','ds_cand_1206','option_d','Ji ber ku ji hesinê sivik hatiye çêkirin li dijî guleyan e','Bi rengê xwe heywanên dirr ditirsîne û ji keriyê dûr dixe','ku'),
  ('5f36571b-10a1-5e06-a477-e94d0e56faa3','ds_cand_1207','option_a','Tenê baca ku ji bo firotina xwêya gulan tê dayîn','Xwêya xwarina ku ji mêvan re tê danîn comerdiya xwediyê malê nîşan dide','ku'),
  ('5f36571b-10a1-5e06-a477-e94d0e56faa3','ds_cand_1207','option_b','Qanûna ku xwarina xwêyê di şîvê de qedexe dike','Şîreta teserûfê ku dibêje divê nan û xwê neyên avêtin','ku'),
  ('5f36571b-10a1-5e06-a477-e94d0e56faa3','ds_cand_1207','option_d','Pêşbirkek ji bo çêkirina nanê herî mezin ê herêmê','Parvekirina wekhev a xwêya ku bi karwanan tê di nav xelkê gund de','ku'),
  ('19add189-7a66-5a18-aa9d-1a4d22707bf1','ds_edebiyat_0244','option_b','Xanî hemû lehengên destanê ji holê rakirine û tenê behsa şerê dîrokî kiriye','Xanî çîroka gelêrî qet neguhertiye, tenê bi tîpên erebî nivîsandiye û berhev kiriye','ku'),
  ('19add189-7a66-5a18-aa9d-1a4d22707bf1','ds_edebiyat_0244','option_c','Memê Alan bi alfabeya latînî hatiye nivîsandin lê Mem û Zîn tenê bi devkî ye','Xanî dawiya trajîk a destanê guhertiye û dawiyeke kêfxweş a gihîştina Mem û Zînê nivîsandiye','ku'),
  ('19add189-7a66-5a18-aa9d-1a4d22707bf1','ds_edebiyat_0244','option_d','Mem û Zîn tenê lîstikeke şanoyê ya nûjen e ku di sedsala bîstan de hatiye nivîsandin','Xanî mesnewî bi farisî nivîsandiye, wergera wê ya kurmancî paşê şagirtên wî amade kiriye','ku'),
  ('19b9848a-6147-5952-819d-abee8a690037','ds_edebiyat_0245','option_a','Nîqaşa li ser bihayê genim û deştên çandiniyê','Dadperweriya mîrên Cizîrê û sivikkirina barê bacê li ser gel','ku'),
  ('19b9848a-6147-5952-819d-abee8a690037','ds_edebiyat_0245','option_b','Diyarkirina rêzikên bazirganiya hevrîşimê li Cizîrê','Kurdî wekî zimanê edebî ne kêmî farisî û erebî ye','ku'),
  ('19b9848a-6147-5952-819d-abee8a690037','ds_edebiyat_0245','option_d','Şerê di navbera împaratoriyên rojava û rojhilat de','Bedewiya biharê û sadebûna jiyana koçeran li zozanan','ku'),
  ('69be4d7f-3805-5891-b6bc-698752e4b998','ds_edebiyat_0246','option_a','Hawar tenê bi zimanê fransî derket, Rêya Teze tenê bi zimanê ermenî bû','Her du jî bi tîpên erebî derketin, lê Rêya Teze nîşanên zêde ji bo dengdêran bi kar anîn','ku'),
  ('69be4d7f-3805-5891-b6bc-698752e4b998','ds_edebiyat_0246','option_c','Hawar tenê kovareke wêneyî bû, Rêya Teze qet tiştek çap nedikir','Hawar bi latînî, Rêya Teze jî ji hejmara xwe ya yekem ve tenê bi kirîlî derket','ku'),
  ('69be4d7f-3805-5891-b6bc-698752e4b998','ds_edebiyat_0246','option_d','Her du weşanan jî tenê alfabeya erebî ya kevn a osmanî bi kar dianî','Hawar bi tîpên erebî, Rêya Teze jî bi tîpên ermenî yên guncandî derket','ku'),
  ('1ea2be4c-5b71-5869-a305-75e6ee313d87','ds_edebiyat_0248','option_b','Hemû cureyên helbestê qedexe kirin û tenê çîrokên zarokan nivîsandin','Helbest ji zimanê gel dûr xist û ber bi zimanekî dîwanê yê bi giranî farisî û erebî ve bir','ku'),
  ('1ea2be4c-5b71-5869-a305-75e6ee313d87','ds_edebiyat_0248','option_c','Helbest tenê bi zimanê latînî yê kevnar di nav dêran de xwend','Erûz bi temamî berda û tenê bi helbesta azad li ser evîn û xwezaya kesane nivîsî','ku'),
  ('1ea2be4c-5b71-5869-a305-75e6ee313d87','ds_edebiyat_0248','option_d','Tenê behsa xwezaya Ewropayê kir û ji jiyana welat bi temamî dûr ket','Kevneşopiya dîwanê ya klasîk wekî xwe domand û mijarên tesewifî ji nû ve vejandin','ku'),
  ('4cf1534a-28ce-5a0c-9b7c-5510b31dd5f4','bilim_0051','option_b','Veguherandina fosfora di axê de bo oksîjena ku riwek dikare bikar bîne','Amonyaka axê oksîde dike û dike nîtrît','ku'),
  ('4cf1534a-28ce-5a0c-9b7c-5510b31dd5f4','bilim_0051','option_c','Depokirina hemû ava ku riwek ji axê dikişîne di girêkên kokê de','Nîtrata ku di kokê de kom bûye wekî gaza nîtrojenê dîsa berdide atmosferê','ku'),
  ('4cf1534a-28ce-5a0c-9b7c-5510b31dd5f4','bilim_0051','option_d','Sekinandina bi tevahî ya çêkirina klorofîlê di pelên riwekê de','Nîtrîta axê vediguherîne nîtrat','ku'),
  ('74eae4a8-7462-5082-8b24-4f565f1cd399','offline_tek_2006','option_a','Ji ber ku av di boriyan de sartir dibe û kêm dibe','Ji ber ku av rasterast digihîje qatên kûr ên axê','ku'),
  ('74eae4a8-7462-5082-8b24-4f565f1cd399','offline_tek_2006','option_c','Ji ber ku dilop ji lehiyê giran in','Ji ber ku ava di boriyan de tê berhevkirin û dîsa tê bikaranîn','ku'),
  ('8800d2fb-b58b-5a97-aeac-15270193a913','offline_6059','explanation_ku','"hewran": kincê dirêj ê ku li ser kincên din tê lixistin.','Hewran kincê dirêj ê derve ye ku li ser kincên din tê lixwekirin; ne qata rojane, qata herî jor e.','ku'),
  ('b0a0fca8-aa88-5f74-a85a-16119b8655eb','offline_6093','explanation_ku','"tûrik": tûrikê ku ji bo hilgirtina xwarinê tê hûnandin.','Tûrik tûrikekî hûnandî ye; ji bo birina nan û zad di rê û zeviyê de tê bikaranîn.','ku'),
  ('a7f1b481-b1e1-5559-975e-c29ae42be8b1','offline_6117','explanation_ku','"nanê tenûrê": nanê kevneşopî yê ku di tenûrê de tê patin.','Nanê tenûrê nanê tenik e ku bi dîwarê hundirê tenûrê ve tê zeliqandin û tê patin; nav jî ji tenûrê tê.','ku'),
  ('4e28dece-a151-5b47-8d78-2abe2bc43d93','offline_6136','explanation_ku','"koçerî": şêwaza jiyana koçeran a ku bi demsalan di navbera zozan û germiyanan de digere.','Koçerî şêwaza jiyanê ye ku li ser koça demsalî ya di navbera zozan û germiyanê de ava bûye; bi heman navî rîtmeke govendê jî heye.','ku'),
  ('992b5825-d7da-528f-84c0-11d4b53b4e4a','offline_6189','explanation_ku','"cîranî": cîrantî û hevkariya civakî.','Cîranî ji peyva "cîran" tê; têkiliya cîrantiyê û alîkariya di navbera cîranan de vedibêje.','ku'),
  ('056a6a6f-6811-5da1-8660-f4e31476c213','offline_6457','explanation_ku','"şabaş": kevneşopiya avêtina baxşîşê ji muzîkjenan re.','Şabaş kevneşopiya dayîna pere an diyariyan e di dawet û şahiyan de; li gelek deveran baxşîşa ku ji muzîkjen û dengbêjan re tê dayîn vedibêje.','ku'),
  ('d82f6053-3c83-5856-a18a-1fcae2184ee1','offline_6465','explanation_ku','"sersal": pîrozkirina serê salê di salnameya gelêrî ya kurdî de.','Sersal ji "ser" û "sal" pêk tê; di salnameya gelêrî de pîrozkirina destpêka sala nû vedibêje.','ku'),
  ('536d2683-b5d1-56db-9934-3c015ffb93d5','offline_6533','explanation_ku','"vegotina çîrokan": vegotina ku ji nifşekî diçe nifşekî din.','Çîrok di kevneşopiya devkî de ji nifşekî bo nifşekî din tên gotin û veguhastin; bi demê re bi nivîsandinê jî tên parastin.','ku'),
  ('c1900627-a209-52f4-a198-d4b85eb58581','offline_6538','explanation_ku','"şevbêrk": civînên şevê yên zivistanê.','Şevbêrk civîna şevên dirêj ên zivistanê ye ku cîran li malekê kom dibin û bi çîrok, kilam û sohbetê dem derbas dikin.','ku'),
  ('6e9f8007-63ad-5c56-b456-42cb3b7a3d93','offline_6730','explanation_ku','"serpêhatî": vegotina bûyerên balkêş ên jiyayî.','Serpêhatî vegotina bûyerên ku hatine jiyîn û ji serê kesekî derbas bûne ye; bi vê yekê ji çîroka xeyalî cuda dibe.','ku'),
  ('aaadbd89-176c-5541-aee0-4a3785b2729f','offline_6835','explanation_ku','"qutik": êlek an cilê kurdî yê kevneşopî.','Qutik navê êlek an kincê jor e di cilên kevneşopî de; vebijarkên din ne cil in, hêmanên din ên çandê ne.','ku'),
  ('8ff79e66-cf2b-526a-b1ad-3c7413d73fc8','offline_6841','explanation_ku','"reşmal": çadira ku ji mûyê reş ê bizinan tê çêkirin.','Reşmal yanî "mala reş": konê koçeran e ku ji mûyê bizinan tê hûnandin; mû di baranê de diwerime û avê bernade.','ku'),
  ('b74aada5-767d-5b34-983c-c53c92f8b4e4','offline_7066','explanation_ku','"Dêrsim 1937": operasyona leşkerî ya 1937-38an û kuştinên girseyî.','Dêrsim 1937–38 operasyona leşkerî ya dewletê ya li herêmê û kuştin û sirgûnên girseyî yên wê demê vedibêje.','ku'),
  ('eecba717-363e-569d-9e6e-3a90d9bae4a2','offline_7145','explanation_ku','"Şêx Seîd": rêberê serhildana 1925an a ji bo mafên kurdan.','Şêx Seîd rêberê serhildana 1925an bû; dîroknas aliyên olî û neteweyî yên serhildanê bi awayên cuda dinirxînin. Serhildan hat tepisandin û Şêx Seîd heman salê li Amedê hat darvekirin.','ku'),
  ('a1f9f20b-0554-5687-9664-e06b387ff657','offline_7151','explanation_ku','"Mîrgeha Babanê": mîrnişîna kurd a bihêz a bi navenda Silêmaniyê.','Mîrgeha Babanê mîrgeheke kurd a bihêz bû ku navenda wê Silêmanî bû; bajar di 1784an de ji aliyê Babaniyan ve hat avakirin.','ku'),
  ('06d3f7a1-e623-5400-a584-b08308cb429d','offline_7223','explanation_ku','"Peymana Qesrişîrînê": peymana ku sînorê Osmanî û Sefewiyan diyar kir.','Peymana Qesrişîrînê (1639) sînorê Osmanî û Sefewiyan rêk xist û parvekirina herêmên kurdan di navbera du dewletan de bi giranî xurt kir.','ku'),
  ('ae03650d-527b-5848-867f-cffc9187f457','offline_7249','explanation_ku','"Şêx Mehmûdê Berzencî": rêberê ku li Iraqê xwe wek padîşahê Kurdistanê ragihand.','Şêx Mehmûdê Berzencî di salên 1920î de li Silêmaniyê xwe wekî padîşahê Kurdistanê ragihand û li dijî rêveberiya Brîtanî li ber xwe da.','ku'),
  ('51cf256f-3581-5fcb-9f08-0229341c4780','offline_7300','explanation_ku','"Mela Mehmûdê Bazîdî": lêkolînerê yekem ê ku adet û kevneşopiyên kurdan berhev kir.','Mela Mehmûdê Bazîdî di sedsala 19an de berhema pêşeng a ku adet û kevneşopiyên kurdan bi kurdî berhev dike amade kir; xebat bi teşwîqa dîplomatê rûs Aleksandr Jaba hat nivîsandin.','ku'),
  ('1a22fe3e-1366-5098-8d04-798bc1e8e936','offline_7417','explanation_ku','"şîroveya dîrokî": derxistina wateyê ji delîlan.','Şîroveya dîrokî berhevkirina delîlên çavkaniyan û derxistina wate û encaman ji wan e; tenê rêzkirina bûyeran ne şîrove ye.','ku'),
  ('cc708a55-98ca-53f1-b6c8-208f802c7df6','offline_7474','explanation','"dîroka devkî": rêbaza têgihiştina rabirdûyê bi şahidî û vegotinan.','Dîroka devkî rabirdûyê bi şahidiyên devkî yên kesên ku ew bûyer jiyane an bihîstine lêkolîn dike; ev şahidî bi belgeyên nivîskî û çavkaniyên din re tên nirxandin.','ku'),
  ('cc708a55-98ca-53f1-b6c8-208f802c7df6','offline_7474','explanation_ku','"dîroka devkî": rêbaza têgihiştina rabirdûyê bi şahidî û vegotinan.','Dîroka devkî rabirdûyê bi şahidiyên devkî yên kesên ku ew bûyer jiyane an bihîstine lêkolîn dike; ev şahidî bi belgeyên nivîskî û çavkaniyên din re tên nirxandin.','ku'),
  ('8614c98b-9514-5398-9501-ba79056f87e4','offline_7497','explanation_ku','"Mistefa Barzanî": rêberê leşkerî û siyasî yê navdar ê tevgera kurdî.','Mistefa Barzanî (1903–1979) bi salan serokatiya leşkerî û siyasî ya tevgera kurdî li Başûrê Kurdistanê kir; di artêşa Komara Mehabadê de jî fermandar bû.','ku'),
  ('5c89b78c-9abb-51c9-b8f7-2d05f939e98b','offline_7507','explanation_ku','"koçberî": guhertina cihê jiyanê ya komên mirovan.','Koçberî guhertina cihê jiyanê ya komên mirovan e ji ber sedemên wekî şer, debar an zordarî; dikare demkî an mayînde be.','ku'),
  ('43d87741-9576-5920-ad2e-10a58a68ce2d','offline_7605','explanation_ku','"çavkaniya seretayî": belge an tiştê ku ji wê serdemê maye.','Çavkaniya seretayî çavkaniyek e ku rasterast li ser mijara lêkolînê şahidiyê dike an daneyên resen pêşkêş dike; belge, tişt û vegotinên şahidên wê serdemê mînakên wê ne.','ku'),
  ('f580690b-21d1-5b8a-9f80-4e1778aeb76f','offline_7643','explanation_ku','"Mîqdat Mîdhad Bedirxan": rojnamevanê kurd ê yekem ê ku rojnameya Kurdistan derxist.','Miqdad Midhad Bedirxan rojnameya kurdî ya yekem, Kurdistan, di 22ê Nîsana 1898an de li Qahîreyê derxist; ev roj wekî roja rojnamegeriya kurdî tê bibîranîn.','ku'),
  ('c6a33f83-73cc-52e7-ab5f-a1440cc5d626','offline_7763','explanation_ku','"Mîrgeha Botan": mîrnişîna kurd a girîng a bi navenda Cizîrê.','Navenda Mîrgeha Botan Cizîr bû (Cizîra Botan); mîrê wê yê mezin ê dawî, Bedirxan Beg, di 1847an de li hember Osmaniyan têk çû.','ku'),
  ('4cbea941-2a07-5c24-8b0b-7576468bc76a','offline_7798','explanation_ku','"Îhsan Nûrî Paşa": efserê ku ji bo Xoybûnê rêberiya leşkerî kir.','Îhsan Nûrî Paşa fermandarê leşkerî yê serhildana Agiriyê (1927–1930) bû ku komeleya Xoybûnê piştgirî dida.','ku'),
  ('ba592679-02c6-5cc1-818b-22f10dcdca19','offline_7852','explanation_ku','"Kovara Hawarê": kovara kurdî ya yekem a ku bi tîpên latînî hat çapkirin.','Kovara Hawarê di 1932an de li Şamê ji aliyê Celadet Alî Bedirxan ve hat derxistin; alfabeya kurmancî ya bi tîpên latînî belav kir.','ku'),
  ('275b9299-3d48-591a-9ea6-492bc702f907','offline_7905','explanation_ku','"Operasyona Enfalê": jenosîda ku rejîma Iraqê li dijî kurdan pêk anî.','Enfal kampanyaya rejîma Baasê ya Iraqê ye ku di 1988an de li dijî kurdan meşand; gund hatin wêrankirin û bi deh hezaran mirov hatin kuştin. Gelek welat û sazî wê wekî jenosîd nas dikin.','ku'),
  ('c362c08b-fe14-517f-8250-4cab07423e09','offline_8023','explanation_ku','"Heskîf": bajarê dîrokî yê hezaran salî yê li ser çemê Dîcleyê.','Heskîf bajarekî pir kevnar e li ser Dîcleyê ku bi şikeftên di zinaran de kolayî tê naskirin; di 2020an de ava Bendava Ilisûyê piraniya bajarê kevn binav kir.','ku'),
  ('181dcca2-6fa9-5d45-8b2c-3c46c4cedb88','offline_8141','explanation_ku','"Gola Derbendîxanê": bendava ku li ser çemê Diyalayê hatiye avakirin.','Gola Derbendîxanê gola çêkirî ye ku bendava li ser Çemê Diyala (Sîrwan) çêkiriye; ne gola xwezayî ye.','ku'),
  ('3ac95f40-e4d2-509a-ac6b-2316aaafff60','offline_8200','explanation_ku','"Deşta Sêwregê": deşta kevirî ya ku ji lavên Karacadaxê pêk hatiye.','Deşta Sêwregê deşteke kevirî ye ku lavên bazaltî yên Qerejdaxê ew nixumandiye; loma axa wê bi kevir e.','ku'),
  ('d5fef95b-da03-593d-80fb-c7853af3eaa1','offline_8255','explanation_ku','"Rêzeçiyayên Zagrosê": çiyayên ku erdnîgariya Kurdistanê ji serî heta binî dabeş dikin.','Rêzeçiyayên Zagrosê ji bakurê rojava ber bi başûrê rojhilat ve dirêj dibin û stûna erdnîgariya Kurdistanê pêk tînin.','ku'),
  ('366222d8-55ed-53e3-ab3a-98012fece2e6','offline_8384','explanation_ku','"Deşta Hewlêrê": deşta çandiniyê ya herî berdar a başûrê Kurdistanê.','Deşta Hewlêrê deşteke berdar e ku di navbera Zapa Mezin û Zapa Biçûk de ye; bi çandiniya dexlê tê naskirin.','ku'),
  ('c33e360d-6b01-535b-9d45-cc6a5899f8f8','offline_8480','explanation_ku','"Qerejdax": volkana bazaltî ya berfireh a li deşta Amedê ye.','Qerejdax volkaneke mertalî ya fireh û nizm e ku di navbera Amed û Rihayê de belav dibe; kevirên bazaltî yên derdora wê di sûrên Amedê de jî hatine bikaranîn.','ku'),
  ('bc8f62d2-023f-5ff9-9866-269807506092','offline_8523','explanation_ku','"Çemê Dîcleyê": çemê ku ji binê sûrên Amedê derbas dibe.','Dîcle di newala binê sûrên dîrokî yên Amedê re diherike; Baxçeyên Hewselê di navbera sûran û çem de ne.','ku'),
  ('cc221d3b-f542-54d4-9969-69e9d9df2f36','offline_8532','explanation_ku','"Gola Dokanê": bendava çêkirî ya li nêzîkî Silêmaniyê.','Gola Dokanê gola çêkirî ye ku bendava li ser Zapa Biçûk çêkiriye û girêdayî parêzgeha Silêmaniyê ye.','ku'),
  ('85e345da-da12-5082-90cc-cced11451cb9','offline_8539','explanation_ku','"Avhewaya Kurdistanê": li deverên parzemînî û çiyayî zivistanên sar.','Li piraniya Kurdistanê avhewaya parzemînî serdest e: ji ber bilindahî û dûrbûna ji deryayê zivistan sar û bi berf, havîn germ û hişk derbas dibin.','ku'),
  ('41665ecf-07e3-5ff9-8e6d-aa347103af83','offline_8603','explanation_ku','"Gola Hazarê": gola tektonîk a li herêma Elezîzê.','Gola Hazarê gola tektonîk e ku li Elezîzê li ser Xeta Şikesta Anatoliya Rojhilat çêbûye; Dîcle ji derdora vê golê derdikeve.','ku'),
  ('eea6815d-efe3-564d-a823-173738e4f778','offline_8950','explanation_ku','"Gola Dokanê": bendava çêkirî ya li nêzîkî Silêmaniyê.','Gola Dokanê bi Bendava Dokanê ya li ser Zapa Biçûk çêbûye û gola çêkirî ye; nêzîkî Silêmaniyê ye.','ku'),
  ('2fe04d59-bcbe-523a-bf78-61f211522280','offline_9132','explanation_ku','"Çemê Xabûrê": şaxê Dîcleyê yê ku sînorê Tirkiye û Iraqê diyar dike.','Çemê Xabûrê şaxekî Dîcleyê ye ku nêzîkî Zaxoyê derbas dibe û tevlî Dîcleyê dibe; beşek ji wî sînorê Tirkiye û Iraqê pêk tîne.','ku'),
  ('3778b742-5722-5f4b-b6fc-c60c0fa3f570','offline_9207','explanation_ku','"Kovara Ronahî": kovara wêjeyî ya ku li Şamê bi tîpên latînî derket.','Kovara Ronahî di navbera 1942 û 1945an de li Şamê ji aliyê Celadet Alî Bedirxan ve hat derxistin; weşana xwişk a Hawarê bû û bi wêne bû.','ku'),
  ('5f0a48c4-22df-58a6-985e-971081806482','offline_9227','explanation_ku','"Cegerxwîn": helbestvanê civakî yê pêşeng ê helbesta kurdî ya modern.','Cegerxwîn (1903–1984) bi sûdwergirtina ji şêweyên klasîk jî di helbesta xwe de jiyana gel, mafên civakî û azadî anî ziman; yek ji pêşengên helbesta kurdî ya civakî ya nûjen tê hesibandin.','ku'),
  ('ff6ea5ed-7d02-518c-8737-82c3e09423ba','offline_9410','explanation_ku','"Destana Memê Alan": destana gelêrî ya ku Ehmedê Xanî ji bo Mem û Zînê jê îlham girtiye.','Memê Alan destaneke gelêrî ya devkî ye; Ehmedê Xanî di mesnewiya Mem û Zînê ya ku di 1692an de nivîsî de ji vê vegotinê sûd wergirt.','ku'),
  ('c2532d7c-87e6-56a9-899f-53defea20d83','offline_9434','explanation_ku','"Rojnameya Riya Taza": rojnameya kurdî ya ku bi salan li Rewanê hat çapkirin.','Riya Teze rojnameya kurdî ye ku di 1930an de li Rewanê dest bi weşanê kir; piştî ku weşana wê demekê sekinî, di 1955an de ji nû ve dest pê kir.','ku'),
  ('ba2759a3-1e8f-58a5-9b65-7c675166802a','offline_9552','explanation_ku','"Mestûre Erdelan": dîroknas û helbestvana kurd a yekem a ku dîwan nivîsandiye.','Mestûre Erdelan (1805–1848) dîroka Mîrgeha Erdelanê nivîsî û helbestên xwe di dîwanekê de kom kirin; wekî dîroknasa kurd a jin a yekem tê bibîranîn.','ku'),
  ('1512d71a-288b-5a23-80db-3b6968d2c79c','offline_9594','explanation_ku','"Nûbihara Biçûkan": ferhenga kurdî ya yekem a ku Ehmedê Xanî nivîsî.','Nûbihara Biçûkan ferhenga erebî–kurdî ya bi helbest e ku Ehmedê Xanî ji bo hînbûna erebî ya zarokan nivîsî; peyv di beytên ji bo jiberkirinê de tên dayîn.','ku'),
  ('421bf996-e228-5b7e-b029-32378213f3e5','offline_9625','explanation_ku','"Osman Sebrî": yek ji navên damezrîner ên çîroknivîsiya kurdî ya modern.','Osman Sebrî (1905–1993) nivîskar û helbestvanekî derdora Hawarê ye; yek ji navên damezrîner ên çîroknivîsiya kurdî ya nûjen tê hesibandin.','ku'),
  ('8d92ec5b-8537-5cf0-99ad-fda48ab582e3','offline_9724','explanation_ku','"Ekola Hawarê": tevgera wêjeyî ya ku ronakbîriya kurdî û alfabeya latînî belav kir.','Ekola Hawarê di salên 1930–40î de li derdora birayên Bedirxan pêş ket; zimanê nivîskî yê kurmancî yê bi tîpên latînî û ronakbîriya kurdî belav kir.','ku'),
  ('c50304aa-5a2e-573f-b066-16598ca81a59','offline_9778','explanation_ku','"Nalî": helbestvanê dîwanê yê herî mezin ê ekola klasîk a soranî.','Nalî helbestvanê dîwanê ye ku di sedsala 19an de, di serdema Mîrgeha Babanê de bi soranî nivîsî; yek ji navên damezrîner ên helbesta klasîk a soranî tê hesibandin.','ku'),
  ('4343de02-d742-5b98-81a5-a309e00d0d0f','offline_10074','explanation_ku','"Dîwana Melayê Cizîrî": dîwana helbestê ya navdar a bi evîna mîstîk û felsefeyê.','Dîwana Melayê Cizîrî evîna tesewifî û ramana felsefî dike mijar; yek ji berhemên helbesta kurmancî ya klasîk e ku herî zêde tên xwendin.','ku'),
  ('b6180e9e-1460-56fd-b07f-409fcd93dc3c','offline_10314','explanation_ku','"awazên Serhedê": şêwaza muzîka lîrîk a taybetî ya devera Qers, Agirî û Wanê.','Awazên Serhedê ji devera Qers, Agirî û Wanê tên; bi gotina dengbêjiyê ya lîrîk û bêhnfireh tên naskirin.','ku'),
  ('11a79256-9ebb-5b2a-8cf5-10c39409d74b','offline_10320','explanation_ku','"dibistana dengbêjiyê": veguhastina muzîkî ya bi têkiliya hoste-şagirt.','Dengbêjî bi têkiliya hoste-şagirt tê hînbûn: dengbêjê ciwan guh dide hosteyê xwe, kilaman jiber dike û şêwaza wî didomîne.','ku'),
  ('65970ee9-2dfb-524e-b130-61cff68f505f','offline_10379','explanation_ku','"meqam": pergala ku avahiya awazê diyar dike.','Meqam pergala rêz û qaîdeyan e ku diyar dike awaz ji kîjan dengan ava dibe û çawa pêş ve diçe; ne rîtmê, awazê birêk dixe.','ku'),
  ('e7333f15-0ae5-594e-b3be-366230238b4b','offline_10423','explanation_ku','"tembûr": amûra têlî ya ku di muzîka gelêrî ya kurdî de herî pîroz tê hesibandin.','Tembûr amûreke têldar a destikdirêj e; di baweriya Yarsanê (Ehlê Heq) de pîroz tê hesibandin û di merasîmên cemê de tê lêdan.','ku'),
  ('5840fb72-4df1-5971-9170-8c40a337bf2b','offline_10480','explanation_ku','"awazên Botanê": muzîka rîtmîk û meqamî ya devera Şirnex û Cizîrê.','Awazên Botanê aîdî devera Şirnex û Cizîrê ne; bi avahiya xwe ya rîtmîk û meqamî ji şêwazên deverên din cuda dibin.','ku'),
  ('74f436dc-cd10-53f9-9655-c003f190d9dc','offline_10498','explanation_ku','"Koma Amed": koma muzîkê ya alternatîf a ku di salên 90î de di muzîka kurdî de şoreş çêkir.','Koma Amed komeke muzîkê ya alternatîf e ku amûrên nûjen û sazkirinên nû anîn muzîka kurdî.','ku'),
  ('199ad51d-6132-58a8-8436-49c6bedef930','offline_10566','explanation_ku','"nota": nîşanên gerdûnî yên ku pê muzîk tê nivîsandin.','Nota pergala nîşanan e ku bilindahî û dirêjahiya dengan bi nivîsê nîşan dide; bi vî awayî awazek ji ser kaxezê tê xwendin û lêdan.','ku'),
  ('4efa354e-b0f0-5425-b4f5-085c3713c393','offline_10572','explanation_ku','"Hesen Cizrawî": dengbêjê ku tomarên muzîka kurdî yên serdema destpêkê çêkirin.','Hesen Cizrawî dengbêjekî ji Cizîrê ye ku bi salan di weşanên kurdî yên Radyoya Bexdayê de kilam gotin.','ku'),
  ('1d460377-37ec-5152-baa9-9436757d7e35','offline_10813','explanation_ku','"kevneşopiya şabaşê": edeta avêtina pereyan ji muzîkjenan re.','Şabaş kevneşopiya dayîna pere an diyariyan e di dawetan de; li gelek deveran baxşîşa ku ji muzîkjenan re tê dayîn jî digire nav xwe.','ku'),
  ('59bfeddd-0c33-5014-9534-3dfbbe134c72','offline_10926','explanation_ku','"Mihemed Şêxo": ozanê ku hestên neteweyî yên gelê kurd dianî ziman.','Mihemed Şêxo (1948–1989) hunermendekî ji Rojava ye; bi stranên xwe yên neteweyî û civakî yên bi tembûrê tê naskirin.','ku'),
  ('40ee687a-2280-566d-b7c9-d3659cf5cde1','offline_11068','explanation_ku','"awazên behdînî": şêwaza muzîkê ya taybetî ya devera Dihok û Zaxoyê.','Awazên behdînî taybetî derdora Dihok û Zaxoyê (Behdînan) ne; bi zarava û rîtmên xwe yên taybet tên naskirin.','ku'),
  ('1a33d5cf-9c5a-5047-9562-e1ef5f9bc716','offline_11136','explanation_ku','"rîtm": lêdanên birêkûpêk ên ku bingeha muzîkê pêk tînin.','Rîtm di muzîkê de ji aliyê dem û giraniyê ve rêkxistina deng û bêdengiyan e; berevajî awazê, ne bilindahiya dengan lê dema wan diyar dike.','ku'),
  ('9b118378-3bf5-58d1-8a3f-aaffb4706c67','offline_11294','explanation_ku','"erbane": defa bi zengil a ku di muzîka gelêrî de belav tê lêxistin.','Erbane defeke mezin e ku zengil an xelek bi çarçoveya wê ve hatine girêdan; di civatên olî û muzîka gelêrî de ji bo rîtmê tê lêxistin.','ku'),
  ('8b73c0ae-af0a-598f-9776-02fa29944ee7','offline_12899','explanation_ku','"nenavendîbûn": belavkirina hêzê ji navendê ber bi yekîneyên herêmî ve.','Di nenavendîbûnê de beşek ji desthilata biryarê ji rêveberiya navendî tê veguhastin bo yekîneyên herêmî yên wekî parêzgeh, herêm û şaredariyan.','ku'),
  ('e953efd8-6f54-5ea2-a72d-d61c0ece7c4a','offline_13040','explanation','"azınlık hakları": parastina komên ku ji piraniyê cuda ne.','Mafên hindikahiyan armanc dikin ku ziman, ol û çanda komên kêmhejmar li hember piraniyê biparêzin.','ku'),
  ('e953efd8-6f54-5ea2-a72d-d61c0ece7c4a','offline_13040','explanation_ku','"azınlık hakları": parastina komên ku ji piraniyê cuda ne.','Mafên hindikahiyan armanc dikin ku ziman, ol û çanda komên kêmhejmar li hember piraniyê biparêzin.','ku'),
  ('12ffd15e-531d-5f5d-9ae0-3031d7c4fd55','offline_13122','explanation','"barış hakkı": mafê gerdûnî yê civakê yê jiyana bêyî şer.','Mafê aştiyê mafê kes û civakan e ku bêyî xetera şer û şîdetê bijîn; di nifşê "mafên piştevaniyê" yê mafên mirovan de tê hejmartin.','ku'),
  ('12ffd15e-531d-5f5d-9ae0-3031d7c4fd55','offline_13122','explanation_ku','"barış hakkı": mafê gerdûnî yê civakê yê jiyana bêyî şer.','Mafê aştiyê mafê kes û civakan e ku bêyî xetera şer û şîdetê bijîn; di nifşê "mafên piştevaniyê" yê mafên mirovan de tê hejmartin.','ku'),
  ('51cd0509-a55f-543e-a98b-d1f1d69a354a','offline_13252','explanation','"insan hakları": mafên gerdûnî yên ku her kes ji dayikbûnê xwedî wan e.','Mafên mirovan mafên gerdûnî ne ku her mirov ji dayikbûnê ve xwedî wan e, bêyî ku bi bexşandina kesekî ve girêdayî bin; Danezana Gerdûnî ya Mafên Mirovan (1948) wan dihejmêre.','ku'),
  ('51cd0509-a55f-543e-a98b-d1f1d69a354a','offline_13252','explanation_ku','"insan hakları": mafên gerdûnî yên ku her kes ji dayikbûnê xwedî wan e.','Mafên mirovan mafên gerdûnî ne ku her mirov ji dayikbûnê ve xwedî wan e, bêyî ku bi bexşandina kesekî ve girêdayî bin; Danezana Gerdûnî ya Mafên Mirovan (1948) wan dihejmêre.','ku'),
  ('26f36d38-a675-5830-99bf-b37e4434dc00','offline_13729','explanation','"müzakere": rêbaza çareserkirina pirsgirêkan bi rêya diyalogê.','Muzakere hewla aliyan e ku pirsgirêkan bêyî bikaranîna hêzê, bi danûstandin û lihevkirinê çareser bikin.','ku'),
  ('26f36d38-a675-5830-99bf-b37e4434dc00','offline_13729','explanation_ku','"müzakere": rêbaza çareserkirina pirsgirêkan bi rêya diyalogê.','Muzakere hewla aliyan e ku pirsgirêkan bêyî bikaranîna hêzê, bi danûstandin û lihevkirinê çareser bikin.','ku'),
  ('c7eb5be1-0bb8-5f79-841a-d4eb05e710ce','offline_13745','explanation','"çoğulculuk": qebûlkirina wekhev a nasname û baweriyên cuda.','Pirrengî diparêze ku nasname, bawerî û nêrînên cuda yên civakê bi hev re û bi wekhevî hebin.','ku'),
  ('c7eb5be1-0bb8-5f79-841a-d4eb05e710ce','offline_13745','explanation_ku','"çoğulculuk": qebûlkirina wekhev a nasname û baweriyên cuda.','Pirrengî diparêze ku nasname, bawerî û nêrînên cuda yên civakê bi hev re û bi wekhevî hebin.','ku'),
  ('4374f3ad-1c34-5e95-b4bc-408be1df17d9','offline_curated_20001','explanation','"ergatîf" tê vê wateyê: avahiya rêzimanî ya ku kirdeya lêkerên gerguhêz di dema borî de tewandî nîşan dide.','Di avahiya ergatîf de kirdeya lêkera gerguhêz di dema borî de tewandî ye: di hevoka "Min nan xwar" de kirde ne "ez", "min" e.','ku'),
  ('4374f3ad-1c34-5e95-b4bc-408be1df17d9','offline_curated_20001','explanation_ku','"ergatîf" tê vê wateyê: avahiya rêzimanî ya ku kirdeya lêkerên gerguhêz di dema borî de tewandî nîşan dide.','Di avahiya ergatîf de kirdeya lêkera gerguhêz di dema borî de tewandî ye: di hevoka "Min nan xwar" de kirde ne "ez", "min" e.','ku'),
  ('9acbc43f-b9d9-585e-8e54-eae85a2dfde6','offline_curated_20026','explanation','"tewandin" tê vê wateyê: guhertina paşgira navdêr an cînavkan li gorî rola wan a di hevokê de.','Tewandin guhertina şeklê navdêr û cînavkan e li gorî rola wan di hevokê de: "ez" bi tewandinê dibe "min", "jin" jî dibe "jinê".','ku'),
  ('9acbc43f-b9d9-585e-8e54-eae85a2dfde6','offline_curated_20026','explanation_ku','"tewandin" tê vê wateyê: guhertina paşgira navdêr an cînavkan li gorî rola wan a di hevokê de.','Tewandin guhertina şeklê navdêr û cînavkan e li gorî rola wan di hevokê de: "ez" bi tewandinê dibe "min", "jin" jî dibe "jinê".','ku'),
  ('f9c06f28-dbe6-5d78-97e4-02d4b5949e98','offline_curated_20051','explanation','"ezafe" tê vê wateyê: têkiliya veqetandeka mê (a) û nêr (ê) ya ku navdêran bi hev ve girê dide.','Veqetandek navdêrê bi peyva piştî xwe ve girê dide: di navdêrên mê de "-a" (mala min), di yên nêr de "-ê" (bavê min).','ku'),
  ('f9c06f28-dbe6-5d78-97e4-02d4b5949e98','offline_curated_20051','explanation_ku','"ezafe" tê vê wateyê: têkiliya veqetandeka mê (a) û nêr (ê) ya ku navdêran bi hev ve girê dide.','Veqetandek navdêrê bi peyva piştî xwe ve girê dide: di navdêrên mê de "-a" (mala min), di yên nêr de "-ê" (bavê min).','ku'),
  ('38fbf109-6c46-570f-83ed-9e1125dc2beb','offline_curated_20076','explanation','"cînavkên tewandî" tê vê wateyê: cînavkên wekî "min, te, wî, wê, me, we, wan" ku di bin tewandinê de ne.','Cînavkên tewandî (min, te, wî, wê, me, we, wan) di hevoka gerguhêz a dema niha de bireser, di ya dema borî de kirde ne: "Ez wî dibînim", "Min ew dît".','ku'),
  ('38fbf109-6c46-570f-83ed-9e1125dc2beb','offline_curated_20076','explanation_ku','"cînavkên tewandî" tê vê wateyê: cînavkên wekî "min, te, wî, wê, me, we, wan" ku di bin tewandinê de ne.','Cînavkên tewandî (min, te, wî, wê, me, we, wan) di hevoka gerguhêz a dema niha de bireser, di ya dema borî de kirde ne: "Ez wî dibînim", "Min ew dît".','ku'),
  ('2b5cf310-88bb-5a54-a88b-d65c756d14bd','offline_curated_20126','explanation','"lêkera gerguhêz" tê vê wateyê: lêkerên ku hewcedariya wan bi bireserê tewandî heye bo temamkirina wateyê.','Lêkerên gerguhêz dikarin bireser bigirin: bi "xwarin" dikare bê gotin ka çi tê xwarin ("Ez nan dixwim"); "hatin" jî negerguhêz e û bireser nagire.','ku'),
  ('2b5cf310-88bb-5a54-a88b-d65c756d14bd','offline_curated_20126','explanation_ku','"lêkera gerguhêz" tê vê wateyê: lêkerên ku hewcedariya wan bi bireserê tewandî heye bo temamkirina wateyê.','Lêkerên gerguhêz dikarin bireser bigirin: bi "xwarin" dikare bê gotin ka çi tê xwarin ("Ez nan dixwim"); "hatin" jî negerguhêz e û bireser nagire.','ku'),
  ('b3d2fac6-10e1-5df6-8cd6-7bcf72f3ac9c','offline_curated_20151','explanation','"rênivîsa Hawarê" tê vê wateyê: pergala alfabeya kurdî ya bi tîpên latînî ku ji aliyê Celadet Bedirxan ve hatibû amadekirin.','Rênivîsa Hawarê alfabeya kurmancî ya latînî ya 31 tîpî ye ku Celadet Alî Bedirxan di 1932an de bi kovara Hawarê belav kir; îro bi berfirehî tê bikaranîn.','ku'),
  ('b3d2fac6-10e1-5df6-8cd6-7bcf72f3ac9c','offline_curated_20151','explanation_ku','"rênivîsa Hawarê" tê vê wateyê: pergala alfabeya kurdî ya bi tîpên latînî ku ji aliyê Celadet Bedirxan ve hatibû amadekirin.','Rênivîsa Hawarê alfabeya kurmancî ya latînî ya 31 tîpî ye ku Celadet Alî Bedirxan di 1932an de bi kovara Hawarê belav kir; îro bi berfirehî tê bikaranîn.','ku'),
  ('3a4274cb-5e1a-5101-b418-3c3ac192d9e1','offline_curated_20176','explanation','"cînavkên kesane" tê vê wateyê: cînavkên wekî "ez, tu, ew, em, hûn, ew" ên ku bo kesan tên bikaranîn.','Cînavkên kesane (ez, tu, ew, em, hûn, ew) rewşa xwerû ya netewandî ne; di dema niha de wekî kirde tên bikaranîn: "Ez diçim".','ku'),
  ('3a4274cb-5e1a-5101-b418-3c3ac192d9e1','offline_curated_20176','explanation_ku','"cînavkên kesane" tê vê wateyê: cînavkên wekî "ez, tu, ew, em, hûn, ew" ên ku bo kesan tên bikaranîn.','Cînavkên kesane (ez, tu, ew, em, hûn, ew) rewşa xwerû ya netewandî ne; di dema niha de wekî kirde tên bikaranîn: "Ez diçim".','ku'),
  ('561527f4-5679-5fe3-83c2-ff90010d2b87','offline_curated_20201','explanation','"dema borî ya dûr" tê vê wateyê: avahiya lêkerê ya ku kiryarek berî kiryareke din a rabirdûyê qediyaye nîşan dide.','Dema borî ya dûr kiryareke ku berî kiryareke din a rabirdûyê temam bûye vedibêje: "Ez hatibûm", "Min xwaribû".','ku'),
  ('561527f4-5679-5fe3-83c2-ff90010d2b87','offline_curated_20201','explanation_ku','"dema borî ya dûr" tê vê wateyê: avahiya lêkerê ya ku kiryarek berî kiryareke din a rabirdûyê qediyaye nîşan dide.','Dema borî ya dûr kiryareke ku berî kiryareke din a rabirdûyê temam bûye vedibêje: "Ez hatibûm", "Min xwaribû".','ku'),
  ('508123b7-3a59-5da3-97d5-4e5567c80bc4','offline_curated_20226','explanation','"paşgirên tewandinê" tê vê wateyê: hêmanên wekî "-î, -ê, -an" ku di tewandina navdêran de cih digirin.','Paşgirên tewandinê li gorî rola navdêrê tên zêdekirin: di nêrê yekjimar de "-î" (mêrî), di mêya yekjimar de "-ê" (jinê), di pirjimar de "-an" (zarokan).','ku'),
