-- Kapışma içerik göçü — BİRLEŞİK (2026-10-29). Opus 5.5 + GPT-6 Astra ortak kararı.
-- Ayrı dosyalar (icerik_kapisma_duzeltme.sql, icerik_kapisma_ku.sql,
-- icerik_kapisma_ku_ek.sql) yerine TEK işlemde uygulanır; o üçü kayıt için
-- duruyor, ÇALIŞTIRILMAZ. Astra incelemesi (DÜZELT): toplam sayı yetmez, her
-- (id, sütun) tek tek doğrulanmalı; metinle eşleşmede tekillik; ortak hedef
-- kontrolü; tek transaction; uygulanmış listeyle geri alma.
--
-- Akış: hedefler → çakışma kontrolü → satır kilidi → ön sınıflama (uygula /
-- yok / zaten / farkli) → beklenen sayılar ve 'yok' kimlik listesi birebir →
-- güncelleme (yalnız değer hâlâ eskiyse) → her uygula satırı yeni değerde,
-- correct_option değişmemiş → commit. Herhangi bir sapma exception = tümü geri.
-- Geri alma: 2026-10-29_icerik_kapisma_birlesik_geri.sql — uygulanan 534
-- (id, gerçek sütun, eski, yeni) kaydının SABİT listesi; sütun yeniden aranmaz,
-- eksik/değişmiş alanda durur.

begin;
create temp table _hedef (
  id uuid, yerel text, sutun text, eski text, yeni text, kaynak text,
  durum text, gercek_sutun text, onceki_dogru text
) on commit drop;

-- Aynı (id, sütun) iki kaynakta hedeflenmesin.
do $$ begin
  if exists (select 1 from _hedef where kaynak <> 'ek' group by id, sutun having count(*) > 1) then
    raise exception 'birlesik: ayni (id, sutun) birden cok kez hedefleniyor';
  end if;
end $$;

-- Hedef satırları kilitle.
select 1 from questions where id in (select id from _hedef) for update;

-- Ön sınıflama: değer okunur, durum yazılır.
create or replace function pg_temp.deger(q questions, s text) returns text language sql immutable as $f$
  select case s when 'explanation' then q.explanation when 'explanation_ku' then q.explanation_ku
    when 'explanation_tr' then q.explanation_tr when 'option_a' then q.option_a when 'option_b' then q.option_b
    when 'option_c' then q.option_c when 'option_d' then q.option_d when 'prompt' then q.prompt end $f$;

update _hedef h set durum = 'yok' where not exists (select 1 from questions q where q.id = h.id);
update _hedef h set onceki_dogru = q.correct_option from questions q where q.id = h.id;
update _hedef h set durum = 'uygula', gercek_sutun = h.sutun from questions q
 where q.id = h.id and h.kaynak <> 'ek' and pg_temp.deger(q, h.sutun) is not distinct from h.eski;
update _hedef h set durum = 'zaten', gercek_sutun = h.sutun from questions q
 where q.id = h.id and h.durum is null and h.kaynak <> 'ek' and pg_temp.deger(q, h.sutun) is not distinct from h.yeni;
-- Ek: eski metin dört şıkta TAM BİR KEZ geçmeli; gerçek sütun kaydedilir.
update _hedef h set durum = 'uygula',
  gercek_sutun = (select s from questions q, unnest(array['option_a','option_b','option_c','option_d']) s
                  where q.id = h.id and pg_temp.deger(q, s) = h.eski)
 where h.kaynak = 'ek' and exists (select 1 from questions q where q.id = h.id and
   (select count(*) from unnest(array[q.option_a,q.option_b,q.option_c,q.option_d]) v where v = h.eski) = 1);
update _hedef set durum = 'farkli' where durum is null;

do $$
begin
  if (select count(*) from _hedef where durum = 'uygula' and kaynak = 'tr') <> 106
     or (select count(*) from _hedef where durum = 'uygula' and kaynak = 'ku') <> 413
     or (select count(*) from _hedef where durum = 'uygula' and kaynak = 'ek') <> 4
     or (select count(*) from _hedef where durum = 'uygula' and kaynak = 'kok') <> 11
     or (select count(*) from _hedef where durum = 'yok' and kaynak = 'tr') <> 18
     or (select count(*) from _hedef where durum = 'yok' and kaynak = 'ku') <> 78
     or exists (select 1 from _hedef where durum in ('farkli', 'zaten')) then
    raise exception 'birlesik: on siniflama beklenenden farkli';
  end if;
  -- Sunucuda olmayan hedefler (id, kaynak, sütun) çokluklarıyla birebir.
  create temp table _beklenen_yok (id uuid, kaynak text, sutun text) on commit drop;
  if exists (select id, kaynak, sutun from _hedef where durum = 'yok'
             except all select id, kaynak, sutun from _beklenen_yok)
     or exists (select id, kaynak, sutun from _beklenen_yok
             except all select id, kaynak, sutun from _hedef where durum = 'yok') then
    raise exception 'birlesik: sunucuda olmayan hedefler beklenen listeyle ayni degil';
  end if;
  -- Ek: metinle bulunan gerçek sütun kuru çalıştırmadakiyle aynı olmalı.
  if exists (select id, sutun, gercek_sutun from _hedef where kaynak = 'ek'
             except all select * from (values
    ('4fccdab1-1beb-534e-a9f8-2c28be060e00'::uuid,'option_b','option_c'),
    ('7c6a799d-67a2-5261-8d52-a289f517c3e2'::uuid,'option_b','option_d'),
    ('7c6a799d-67a2-5261-8d52-a289f517c3e2'::uuid,'option_c','option_b'),
    ('d5d1dc8d-428e-5d48-865f-1693c1ce35ed'::uuid,'option_b','option_c')) e(id, sutun, gercek))
     or exists (select * from (values
    ('4fccdab1-1beb-534e-a9f8-2c28be060e00'::uuid,'option_b','option_c'),
    ('7c6a799d-67a2-5261-8d52-a289f517c3e2'::uuid,'option_b','option_d'),
    ('7c6a799d-67a2-5261-8d52-a289f517c3e2'::uuid,'option_c','option_b'),
    ('d5d1dc8d-428e-5d48-865f-1693c1ce35ed'::uuid,'option_b','option_c')) e(id, sutun, gercek)
             except all select id, sutun, gercek_sutun from _hedef where kaynak = 'ek') then
    raise exception 'birlesik: ek sutunlari kuru calistirmadan farkli';
  end if;
end $$;

do $$
declare r record; n int;
begin
  for r in select * from _hedef where durum = 'uygula' loop
    execute format('update questions set %I = $1 where id = $2 and %I is not distinct from $3',
                   r.gercek_sutun, r.gercek_sutun) using r.yeni, r.id, r.eski;
    get diagnostics n = row_count;
    if n <> 1 then raise exception 'birlesik: % % guncellenemedi', r.yerel, r.gercek_sutun; end if;
  end loop;
end $$;

do $$
declare n int;
begin
  select count(*) into n from _hedef h join questions q on q.id = h.id
   where h.durum = 'uygula' and pg_temp.deger(q, h.gercek_sutun) is distinct from h.yeni;
  if n > 0 then raise exception 'birlesik: % alan yeni degerde degil', n; end if;
  select count(*) into n from _hedef h join questions q on q.id = h.id
   where h.durum = 'uygula' and q.correct_option is distinct from h.onceki_dogru;
  if n > 0 then raise exception 'birlesik: correct_option degisti (% satir)', n; end if;
end $$;

commit;
